/**
 * @module agentFeedbackStore
 * @description Agent 反馈 Store — 反馈收集、评分汇总、状态管理
 * @created 2026-07-04
  * @doc [V9-DOC-AI-003, V9-DOC-AI-006, V9-DOC-AI-002, V9-DOC-DATA-031, V9-DOC-DATA-032]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { AgentFeedback, AgentFeedbackSummary } from '@/types/modules/agent.types'

const logger = getLogger()

interface AgentFeedbackState {
  feedbacks: AgentFeedback[]
  summaries: Map<string, AgentFeedbackSummary>
  isLoading: boolean

  addFeedback: (feedback: AgentFeedback) => void
  resolveFeedback: (id: string) => void
  getSummary: (agentId: string) => AgentFeedbackSummary
  refreshSummaries: () => void
  /** 重置 store 到初始空状态，清除全部反馈和汇总缓存 */
  reset: () => void
}

/**
 * useAgentFeedbackStore
 */
export const useAgentFeedbackStore = create<AgentFeedbackState>((set, get) => ({
  feedbacks: [],
  summaries: new Map(),
  isLoading: false,

  addFeedback: (feedback) => {
    set((s) => ({
      feedbacks: [...s.feedbacks, feedback],
    }))
    logger.info('[AgentFeedbackStore] Feedback added', {
      taskId: feedback.taskId,
      rating: feedback.rating,
    })
  },

  resolveFeedback: (id) => {
    set((s) => ({
      feedbacks: s.feedbacks.map((f) => (f.id === id ? { ...f, resolved: true } : f)),
    }))
    logger.info('[AgentFeedbackStore] Feedback resolved', { id })
  },

  getSummary: (agentId) => {
    const feedbacks = get().feedbacks.filter((f) => f.agentId === agentId)
    if (feedbacks.length === 0) {
      return { agentId, averageRating: 0, totalFeedback: 0, categoryBreakdown: {} }
    }
    const avgRating = feedbacks.reduce((sum, f) => sum + f.rating, 0) / feedbacks.length
    const breakdown: Record<string, number> = {}
    for (const f of feedbacks) {
      if (f.category == null) {
        logger.warn('[agentFeedbackStore] 字段缺失，使用默认值', { field: 'category', context: `agentId=${f.agentId}` })
        continue // 跳过无分类的反馈，避免污染 breakdown 数据
      }
      const count = breakdown[f.category] ?? 0
      breakdown[f.category] = count + 1
    }
    return {
      agentId,
      averageRating: Math.round(avgRating * 10) / 10,
      totalFeedback: feedbacks.length,
      categoryBreakdown: breakdown,
    }
  },

  refreshSummaries: () => {
    const agents = [...new Set(get().feedbacks.map((f) => f.agentId))]
    const map = new Map<string, AgentFeedbackSummary>()
    for (const agentId of agents) {
      map.set(agentId, get().getSummary(agentId))
    }
    set({ summaries: map })
    logger.info('[AgentFeedbackStore] Summaries refreshed', { count: map.size })
  },

  reset: () => {
    logger.info('[AgentFeedbackStore] reset')
    set({
      feedbacks: [],
      summaries: new Map(),
      isLoading: false,
    })
  },
}))

/**
 * @doc [V9-DOC-PROJ-079, V9-DOC-PROJ-113, V9-DOC-BACK-004, V9-DOC-PROJ-107, V9-DOC-PROJ-053]
 */
// @module analysisNewsStore
// @lifecycle @Analysis
// 分析舱-智能资讯页面的全局状态管理（Zustand）。
// 从 analysis/NewsPage 组件内 4 个 useState 迁移至独立 Store。
//
// 管理范围：
// - 数据层：articles / loading
// - UI 层：filter / selectedArticle
//
// @migration 从 analysis/NewsPage.tsx 的 4 个 useState 迁移而来
import { create } from 'zustand'
import type { NewsArticle } from '@/data/types'
import type { NewsFilterState } from '@/types/modules/news.types'
import { listNews, saveNewsArticles } from '@/services/news/newsService'
import { generateMockArticles } from '@/services/news/newsService'
import {
  aggregateSentimentTrend,
  extractStockOptions,
  extractIndustryOptions,
} from '@/services/news/sentimentTrendEngine'
import type { SentimentTrendDimension, SentimentTrendSeries } from '@/types/modules/news.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export interface AnalysisNewsState {
  articles: NewsArticle[]
  loading: boolean
  filter: NewsFilterState
  selectedArticle: NewsArticle | null
  /** 情感趋势数据 */
  sentimentTrend: SentimentTrendSeries | null
  /** 股票选项列表 */
  sentimentStockOptions: string[]
  /** 行业选项列表 */
  sentimentIndustryOptions: string[]

  // Actions
  setArticles: (articles: NewsArticle[]) => void
  setLoading: (loading: boolean) => void
  setFilter: (filter: NewsFilterState) => void
  selectArticle: (article: NewsArticle | null) => void
  reset: () => void
  fetchArticles: () => Promise<void>
  // @compliance [DF-002] generateMockArticles 封装 Service 调用，组件通过 Store action 间接调用
  // 整改背景：原 NewsPage 直接 import Service 函数，现通过 Store action 中转
  // 相关规范：docs/explanation/design/data-flow-spec.md 第5.1节
  generateMockArticles: () => Promise<void>
  /** 计算情感趋势（封装 sentimentTrendEngine 的聚合与选项提取） */
  computeSentimentTrend: (dimension: SentimentTrendDimension, value?: string) => void
}

const DEFAULT_FILTER: NewsFilterState = {
  keyword: '',
  category: '',
  sentiment: '',
  source: '',
}

const initialState = {
  articles: [] as NewsArticle[],
  loading: false,
  filter: { ...DEFAULT_FILTER },
  selectedArticle: null as NewsArticle | null,
  sentimentTrend: null as SentimentTrendSeries | null,
  sentimentStockOptions: [] as string[],
  sentimentIndustryOptions: [] as string[],
}

/**
 * useAnalysisNewsStore
 */
export const useAnalysisNewsStore = create<AnalysisNewsState>((set, get) => ({
  ...initialState,

  setArticles: (articles) => set({ articles }),
  setLoading: (loading) => set({ loading }),
  setFilter: (filter) => set({ filter }),
  selectArticle: (article) => set({ selectedArticle: article }),

  reset: () => set(initialState),

  fetchArticles: async () => {
    const { filter } = get()
    set({ loading: true })
    try {
      const result = await listNews({
        keyword: filter.keyword || undefined,
        category: filter.category || undefined,
        sentiment: filter.sentiment || undefined,
        source: filter.source || undefined,
      })
      if (result.success && result.data) {
        set({ articles: result.data })
      }
    } finally {
      set({ loading: false })
    }
  },

  // @compliance [DF-002] generateMockArticles 封装 Service 调用
  // - 防重入锁：通过 loading 状态防止并发调用
  // - 日志追踪：logger.info 打印核心分支
  generateMockArticles: async () => {
    // 生产环境禁止生成 Mock 资讯并持久化到 DB
    if (import.meta.env.PROD) {
      logger.warn('[analysisNewsStore] generateMockArticles: 生产环境禁用')
      return
    }
    const { loading } = get()
    // @note 防重入锁
    if (loading) {
      logger.info('[analysisNewsStore] generateMockArticles skipped: loading=true')
      return
    }
    set({ loading: true })
    try {
      const mockArticles = generateMockArticles(5)
      const saveResult = await saveNewsArticles(mockArticles)
      if (saveResult.success) {
        logger.info('[analysisNewsStore] generateMockArticles: saved', {
          count: saveResult.data?.length ?? 0,
        })
        // 保存成功后刷新列表
        const { fetchArticles } = get()
        await fetchArticles()
        logger.info('[analysisNewsStore] generateMockArticles: refreshed list')
      } else {
        logger.info('[analysisNewsStore] generateMockArticles: save failed', {
          error: saveResult.error,
        })
      }
    } finally {
      set({ loading: false })
    }
  },

  computeSentimentTrend: (dimension, value) => {
    const { articles } = get()
    logger.info('[analysisNewsStore] computeSentimentTrend', { dimension, value, articleCount: articles.length })

    const stockOptions = extractStockOptions(articles)
    const industryOptions = extractIndustryOptions(articles)
    const trend = aggregateSentimentTrend(articles, {
      dimension,
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
      value: value || undefined,
      fillGaps: true,
    })

    set({
      sentimentTrend: trend,
      sentimentStockOptions: stockOptions,
      sentimentIndustryOptions: industryOptions,
    })
    logger.info('[analysisNewsStore] computeSentimentTrend 完成', {
      pointCount: trend.data.length,
      stockOptions: stockOptions.length,
      industryOptions: industryOptions.length,
    })
  },
}))

/**
 * @module analysisStore
 * @description 分析舱（AnalysisApp）状态管理层。集中管理分析标的列表、V6 批量评分及加载状态。
 * 从 AnalysisApp 组件中抽取的 3 个 useState，实现 Store 化。
 *
 * @status AnalysisApp.tsx 已接入 useAnalysisStore（stocks/scores/loadStocks/handleScore 等）。
 *
 * @see @/apps/analysis/AnalysisApp.tsx - 消费方
 * @see @/services/analysis/analysisService.ts - 底层数据服务
 * @see @/services/scoring/v6ScoreService.ts - V6 评分计算服务
  * @doc [V9-DOC-PROJ-053, V9-DOC-BACK-006, V9-DOC-PROJ-124, V9-DOC-PROJ-107, V9-DOC-PROD-001]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { Stock, V6Score } from '@/data/types'
import { listStocks, listV6Scores } from '@/services/analysis/analysisService'
import { runV6Score } from '@/services/scoring/v6ScoreService'
import {
  loadIndustryScoreTrend,
  loadStockScoreTrend,
  type ScoreTrendData,
  type ScoreTrendEntityType,
  type ScoreTrendPeriod,
} from '@/services/analysis/scoreTrendService'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID } from '@/config/dbConfig'
import { createTraceId } from '@/lib/utils'

const logger = getLogger()

// ============================================================
// Store 接口
// ============================================================

interface AnalysisState {
  /** 分析标的列表 */
  stocks: Stock[]
  /** V6 评分列表 */
  scores: V6Score[]
  /** 加载状态（标的加载 / 评分计算共用） */
  loading: boolean
  /** 错误信息 */
  error: string | null

  /** 多周期趋势数据 */
  trendData: ScoreTrendData | undefined
  /** 趋势加载状态 */
  trendLoading: boolean
  /** 趋势错误信息 */
  trendError: string | null
  /** 当前趋势周期 */
  trendPeriod: ScoreTrendPeriod

  // Actions
  /** 加载标的列表并刷新评分 */
  loadStocks: () => Promise<void>
  /** 对指定标的运行 V6 评分，完成后自动刷新评分列表 */
  handleScore: (symbol: string) => Promise<void>
  /** 刷新评分列表（静默） */
  loadScores: () => Promise<void>
  /** 清空错误 */
  clearError: () => void
  /** 切换趋势周期 */
  setTrendPeriod: (period: ScoreTrendPeriod) => void
  /** 加载指定实体（行业/个股）的多周期趋势 */
  loadTrend: (entityId: string, entityType: ScoreTrendEntityType, period?: ScoreTrendPeriod) => Promise<void>
  /** 清空趋势错误 */
  clearTrendError: () => void
  /** 重置 Store 到初始状态 */
  reset: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  stocks: [] as Stock[],
  scores: [] as V6Score[],
  loading: false,
  error: null as string | null,
  trendData: undefined as ScoreTrendData | undefined,
  trendLoading: false,
  trendError: null as string | null,
  trendPeriod: 'month' as ScoreTrendPeriod,
}

// ============================================================
// Store
// ============================================================

/**
 * useAnalysisStore
 */
export const useAnalysisStore = create<AnalysisState>((set, get) => ({
  ...initialState,

  loadStocks: async () => {
    logger.info('[analysisStore] loadStocks 开始')
    set({ loading: true, error: null })

    try {
      const result = await listStocks()
      if (result.success && result.data) {
        set({ stocks: result.data, loading: false })
        logger.info(`[analysisStore] loadStocks 完成: ${result.data.length} 只标的`)
      } else {
        const message = result.error ?? '无法加载标的列表'
        logger.error(`[analysisStore] loadStocks 失败: ${message}`)
        set({ loading: false, error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : '无法加载标的列表'
      logger.error(`[analysisStore] loadStocks 异常: ${message}`)
      set({ loading: false, error: message })
    }
  },

  handleScore: async (symbol: string) => {
    logger.info(`[analysisStore] handleScore 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await runV6Score(symbol)
      if (result.success && result.data) {
        const newScores = get().scores.map((s) =>
          s.symbol === symbol ? result.data! : s,
        )
        if (!newScores.some((s) => s.symbol === symbol)) {
          newScores.push(result.data)
        }
        set({ scores: newScores, loading: false })
        logger.info(`[analysisStore] handleScore 完成: ${symbol}`)
        // D-3: 广播评分变更事件
        withBroadcast(EVENT_NAMES.SCORES_CHANGED, { action: 'score', symbol })
        // B6 修复：评分计算完成后通过 DataBridge 信封协议持久化到 v6Scores（刷新后不丢失）
        try {
          await dataBridge.forward(
            EnvelopeFactory.create(
              {
                source: MODULE_ID.analyzer,
                target: ENVELOPE_TARGET.db,
                action: ENVELOPE_ACTION.saveScores,
                traceId: createTraceId('analysis-score'),
              },
              result.data,
            ),
          )
          logger.info(`[analysisStore] handleScore 已持久化: ${symbol}`)
        } catch (persistErr) {
          logger.warn(`[analysisStore] handleScore 持久化失败（不影响内存评分）: ${symbol}`, {
            error: persistErr,
          })
        }
      } else {
        const message = result.error ?? `无法对 ${symbol} 运行评分`
        logger.error(`[analysisStore] handleScore 失败: ${message}`)
        set({ loading: false, error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : `无法对 ${symbol} 运行评分`
      logger.error(`[analysisStore] handleScore 异常: ${message}`)
      set({ loading: false, error: message })
    }
  },

  loadScores: async () => {
    logger.info('[analysisStore] loadScores 开始')
    try {
      const result = await listV6Scores()
      if (result.success && result.data) {
        set({ scores: result.data })
        logger.info(`[analysisStore] loadScores 完成: ${result.data.length} 条评分`)
        // D-3: 广播评分变更事件
        withBroadcast(EVENT_NAMES.SCORES_CHANGED, { action: 'load', count: result.data.length })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[analysisStore] loadScores 异常: ${message}`)
    }
  },

  clearError: () => {
    set({ error: null })
  },

  setTrendPeriod: (period) => {
    set({ trendPeriod: period })
  },

  loadTrend: async (entityId, entityType, period) => {
    const effectivePeriod = period ?? get().trendPeriod
    logger.info(`[analysisStore] loadTrend 开始: ${entityType}=${entityId}, period=${effectivePeriod}`)
    set({ trendLoading: true, trendError: null, trendPeriod: effectivePeriod })

    try {
      const result = entityType === 'industry'
        ? await loadIndustryScoreTrend(entityId, effectivePeriod)
        : await loadStockScoreTrend(entityId, effectivePeriod)

      if ('data' in result) {
        const data = result.data
        set({ trendData: data, trendLoading: false })
        logger.info(`[analysisStore] loadTrend 完成: ${data.points.length} 个周期点`)
      } else {
        const message = result.error ?? '无法加载趋势数据'
        logger.error(`[analysisStore] loadTrend 失败: ${message}`)
        set({ trendLoading: false, trendError: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : '无法加载趋势数据'
      logger.error(`[analysisStore] loadTrend 异常: ${message}`)
      set({ trendLoading: false, trendError: message })
    }
  },

  clearTrendError: () => {
    set({ trendError: null })
  },

  reset: () => {
    logger.info('[analysisStore] reset')
    set({ ...initialState })
  },
}))

// ============================================================
// 派生查询（从 .derived.ts 统一导出，含 memoizeByRef 缓存优化）
// 设计原则：派生查询独立函数模式，通过 getState() 访问状态，不存入 State
// ============================================================
export * from './analysisStore.derived'

/**
 * @module backtestStore
 * @lifecycle @Global
 * @description 策略回测状态管理。支持三种回测策略（热门板块/价值洼地/复合策略），
 * 从 dataLayer.orders 获取历史交易数据，模拟回测计算净值曲线与绩效指标。
 *
 * @compliance
 * - 遵循 Zustand store 模式（参考 holdingsStore.ts）
 * - DataBridge 订阅采用显式 init/destroy 生命周期管理
 * - 模拟算法仅用于当前阶段，后续可接入真实回测引擎
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-076, V9-DOC-DATA-075, V9-DOC-DATA-073]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, MODULE_ID, STORE_NAME } from '@/config/dbConfig'
import type { StandardEnvelope } from '@/core/envelope'
import { BacktestEngine } from '@/services/backtest'
import type { BacktestExportConfig, BacktestExportResult, BacktestStrategy, BacktestHistoryRecord, BacktestHistoryQuery } from '@/types/modules/backtest.types'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

// Re-export BacktestStrategy for backward compatibility
export type { BacktestStrategy }

export interface BacktestTrade {
  symbol: string
  direction: 'buy' | 'sell'
  price: number
  quantity: number
  date: string
  pnl: number
  pnlPct: number
  reason: string
}

export interface BacktestResult {
  totalReturn: number
  annualizedReturn: number
  maxDrawdown: number
  sharpeRatio: number
  winRate: number
  tradeCount: number
  profitTrades: number
  lossTrades: number
  avgProfit: number
  avgLoss: number
  pnlCurve: number[]
  trades: BacktestTrade[]
  /** 最终持仓快照（导出用，由 BacktestEngine 计算） */
  positions?: BacktestPosition[]
  /** 每日净值序列（导出用，由 BacktestEngine 计算） */
  dailyValues?: BacktestDailyValue[]
}

/** 回测持仓快照 */
export interface BacktestPosition {
  symbol: string
  quantity: number
  avgCost: number
  currentPrice: number
  marketValue: number
  unrealizedPnL: number
}

/** 单日净值记录 */
export interface BacktestDailyValue {
  date: string
  totalValue: number
  cash: number
}

export interface BacktestConfig {
  strategy: BacktestStrategy
  startDate: string
  endDate: string
  initialCapital: number
}

interface BacktestState {
  // ---- 回测配置 ----
  config: BacktestConfig

  // ---- 回测结果 ----
  results: BacktestResult | null

  // ---- 回测历史记录 ----
  history: BacktestHistoryRecord[]

  // ---- 加载 / 错误 ----
  loading: boolean
  error: string | null
  lastRunAt: number | null

  // ---- Actions ----
  setConfig: (partial: Partial<BacktestConfig>) => void
  runBacktest: () => Promise<void>
  clearResults: () => void
  /** 按 ID 获取历史回测记录 */
  getBacktestById: (id: string) => BacktestHistoryRecord | undefined
  /** 查询历史回测记录 */
  listBacktestHistory: (query?: BacktestHistoryQuery) => BacktestHistoryRecord[]
  /** 导出当前回测报告（封装 backtestExportService，避免页面直接调用 Service） */
  exportReport: (
    results: BacktestResult,
    config: BacktestConfig,
    options: BacktestExportConfig,
  ) => Promise<BacktestExportResult>
  /** 按历史记录 ID 导出回测报告 */
  exportReportById: (id: string, options: BacktestExportConfig) => Promise<BacktestExportResult>
}

// ============================================================
// 常量
// ============================================================

const DEFAULT_CAPITAL = 1_000_000

function getDefaultDateRange(): { start: string; end: string } {
  const end = new Date()
  const start = new Date()
  start.setFullYear(start.getFullYear() - 1)
  return {
    start: start.toISOString().slice(0, 10),
    end: end.toISOString().slice(0, 10),
  }
}

const defaultDates = getDefaultDateRange()

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  config: {
    strategy: 'hot_sector' as BacktestStrategy,
    startDate: defaultDates.start,
    endDate: defaultDates.end,
    initialCapital: DEFAULT_CAPITAL,
  },
  results: null as BacktestResult | null,
  history: [] as BacktestHistoryRecord[],
  loading: false,
  error: null as string | null,
  lastRunAt: null as number | null,
}

// ============================================================
// Store
// ============================================================

/**
 * useBacktestStore
 */
export const useBacktestStore = create<BacktestState>((set, get) => ({
  ...initialState,

  setConfig: (partial) =>
    set((state) => ({
      config: { ...state.config, ...partial },
    })),

  runBacktest: async () => {
    const { config } = get()
    set({ loading: true, error: null })

    try {
      logger.info('[backtestStore] runBacktest started', { config })

      // 执行基于真实策略信号的回测
      const engine = new BacktestEngine()
      const engineResult = await engine.run({
        ...config,
        commissionRate: 0.0003,
        slippage: 0.001,
        maxPositionPct: 0.2,
      })

      const record: BacktestHistoryRecord = {
        id: nanoid(),
        config: { ...config },
        result: engineResult.metrics,
        createdAt: Date.now(),
      }

      set((state) => ({
        results: engineResult.metrics,
        history: [record, ...state.history].slice(0, 50), // 保留最近 50 条
        loading: false,
        lastRunAt: Date.now(),
      }))

      logger.info('[backtestStore] runBacktest completed', {
        totalReturn: engineResult.metrics.totalReturn,
        sharpeRatio: engineResult.metrics.sharpeRatio,
        tradeCount: engineResult.metrics.tradeCount,
        recordId: record.id,
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : '回测执行失败'
      logger.error('[backtestStore] runBacktest failed', { error: message })
      set({
        loading: false,
        error: message,
        results: null,
      })
    }
  },

  clearResults: () => {
    set({
      results: null,
      error: null,
      lastRunAt: null,
    })
    withBroadcast(EVENT_NAMES.BACKTEST_CHANGED, { action: 'clearResults' })
  },

  exportReport: async (results, config, options) => {
    logger.info('[backtestStore] exportReport started', { format: options.format })
    try {
      const { exportBacktestReport } = await import('@/services/export/backtestExportService')
      const result = await exportBacktestReport(results, config, options)
      logger.info('[backtestStore] exportReport completed')
      return result
    } catch (err) {
      const message = err instanceof Error ? err.message : '导出失败'
      logger.error('[backtestStore] exportReport failed', { error: message })
      throw err
    }
  },

  getBacktestById: (id) => {
    const { history } = get()
    return history.find((r) => r.id === id)
  },

  listBacktestHistory: (query) => {
    const { history } = get()
    let filtered = [...history]
    const { strategy, fromDate, toDate, limit } = query ?? {}

    if (strategy) {
      filtered = filtered.filter((r) => r.config.strategy === strategy)
    }
    if (fromDate !== undefined) {
      filtered = filtered.filter((r) => r.createdAt >= fromDate)
    }
    if (toDate !== undefined) {
      filtered = filtered.filter((r) => r.createdAt <= toDate)
    }
    if (limit && limit > 0) {
      filtered = filtered.slice(0, limit)
    }

    return filtered
  },

  exportReportById: async (id, options) => {
    const record = get().getBacktestById(id)
    if (!record) {
      const msg = `未找到回测记录: ${id}`
      logger.error('[backtestStore] exportReportById failed', { error: msg })
      throw new Error(msg)
    }
    logger.info('[backtestStore] exportReportById started', { id, format: options.format })
    try {
      const { exportBacktestReport } = await import('@/services/export/backtestExportService')
      const result = await exportBacktestReport(record.result, record.config, options)
      logger.info('[backtestStore] exportReportById completed', { id })
      return result
    } catch (err) {
      const message = err instanceof Error ? err.message : '导出失败'
      logger.error('[backtestStore] exportReportById failed', { error: message, id })
      throw err
    }
  },
}))

// ============================================================
// DataBridge 订阅生命周期
// ============================================================

/** 本模块 ID，用于 source 过滤，防止自激 */
const _MODULE_SOURCE = MODULE_ID.tradinghub

/** 去抖合并窗口（毫秒）：短时间内多次变更合并为一次处理 */
const DEBOUNCE_MS = 100

let _unsubscribeOrders: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null
let _pendingEvents: StandardEnvelope[] = []

/** 去抖处理订单变更事件，100ms 内多次调用合并为一次 */
function _debouncedHandleOrders(envelope: StandardEnvelope): void {
  _pendingEvents.push(envelope)
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
  }
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    const events = _pendingEvents
    _pendingEvents = []
    logger.info('[backtestStore] Debounced order events processed', {
      count: events.length,
      actions: events.map((e) => e.meta.action),
      traceId: events[events.length - 1]?.meta.traceId,
    })
  }, DEBOUNCE_MS)
}

/** 初始化 DataBridge 订单频道订阅，返回 cleanup 函数 */
export function initBacktestStoreSubscriptions(): () => void {
  if (_unsubscribeOrders) {
    logger.warn('[backtestStore] Subscriptions already initialized, skipping')
    return _unsubscribeOrders
  }

  const dataBridgeUnsub = dataBridge.subscribe(
    STORE_NAME.orders,
    (envelope) => {
      // source 过滤：跳过本模块发出的事件，防止自激
      if (envelope.meta.source === _MODULE_SOURCE) {
        return
      }

      if (envelope.meta.action === ENVELOPE_ACTION.insertOrder) {
        logger.info('[backtestStore] DataBridge event received: insertOrder', {
          traceId: envelope.meta.traceId,
          source: envelope.meta.source,
        })
        _debouncedHandleOrders(envelope)
      }
      if (envelope.meta.action === ENVELOPE_ACTION.updateOrder) {
        logger.info('[backtestStore] DataBridge event received: updateOrder', {
          traceId: envelope.meta.traceId,
        })
        _debouncedHandleOrders(envelope)
      }
      if (envelope.meta.action === ENVELOPE_ACTION.deleteOrder) {
        logger.info('[backtestStore] DataBridge event received: deleteOrder', {
          traceId: envelope.meta.traceId,
        })
        _debouncedHandleOrders(envelope)
      }
    },
  )

  logger.info('[backtestStore] DataBridge orders subscriptions initialized')

  const cleanup = () => {
    if (_debounceTimer) {
      clearTimeout(_debounceTimer)
      _debounceTimer = null
    }
    _pendingEvents = []
    dataBridgeUnsub()
    _unsubscribeOrders = null
    logger.info('[backtestStore] DataBridge subscriptions destroyed')
  }

  // 以返回的 cleanup 作为已初始化的守卫，保证重复初始化返回同一函数引用
  _unsubscribeOrders = cleanup
  return cleanup
}

/**
 * @module chatStore.derived
 * @description chatStore 派生查询函数集合
 *
 * 设计原则：
 *   1. 纯函数：通过 useChatStore.getState() 访问状态
 *   2. 性能优化：memoizeByRef 缓存无参数派生（messages 引用未变时直接返回缓存）
 *   3. 派生不调用派生：messageStats 直接遍历 messages，避免调用 messagesByRole
 *   4. 空状态安全
 *
 * @compliance AGENTS.md §一 分层规则
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-076, V9-DOC-DATA-075, V9-DOC-DATA-073]
*/

import { useChatStore } from '@/store/chatStore'
import type { ChatMessage } from '@/store/chatStore'
import { memoizeByRef, safeLength } from '@/lib/derivedCache'

// ============================================================
// 类型定义
// ============================================================

/** 消息角色 */
export type MessageRole = 'user' | 'assistant' | 'system'

/** 消息统计 */
export interface MessageStats {
  user: number
  assistant: number
  system: number
  total: number
}

// ============================================================
// 派生查询：基础聚合
// ============================================================

/**
 * 消息总数
 */
export function messageCount(): number {
  return safeLength(useChatStore.getState().messages)
}

/**
 * 是否有消息
 */
export function hasMessages(): boolean {
  return useChatStore.getState().messages.length > 0
}

/**
 * 是否为空（无消息）
 */
export function isEmpty(): boolean {
  return useChatStore.getState().messages.length === 0
}

/**
 * 综合加载状态（正在流式接收）
 */
export function isLoading(): boolean {
  return useChatStore.getState().isStreaming
}

/**
 * 综合错误
 */
export function hasError(): boolean {
  return useChatStore.getState().error !== null
}

// ============================================================
// 派生查询：消息访问（必需）
// ============================================================

/**
 * 最后一条消息
 */
export function lastMessage(): ChatMessage | null {
  const messages = useChatStore.getState().messages
  if (messages.length === 0) return null
  return messages[messages.length - 1]!
}

/**
 * 最后一条用户消息
 */
export function lastUserMessage(): ChatMessage | null {
  const messages = useChatStore.getState().messages
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i]!.role === 'user') return messages[i]!
  }
  return null
}

/**
 * 最后一条 assistant 消息
 */
export function lastAssistantMessage(): ChatMessage | null {
  const messages = useChatStore.getState().messages
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i]!.role === 'assistant') return messages[i]!
  }
  return null
}

/**
 * 当前正在流式接收的消息
 */
export function currentStreamingMessage(): ChatMessage | null {
  const messages = useChatStore.getState().messages
  if (!useChatStore.getState().isStreaming) return null
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i]!.isStreaming) return messages[i]!
  }
  return null
}

// ============================================================
// 派生查询：发送状态（必需）
// ============================================================

/**
 * 是否可发送消息（!isStreaming && !error）
 * UI 场景：StockChatWidget 发送按钮的禁用判定
 */
export function canSend(): boolean {
  const state = useChatStore.getState()
  return !state.isStreaming && state.error === null
}

/**
 * 流式响应进度（已接收字符数/总预估字符数）
 * 注意：此为粗略估算，实际进度需 LLM 服务支持
 */
export function streamingProgress(): number {
  const state = useChatStore.getState()
  if (!state.isStreaming) return 1

  const streamingMsg = currentStreamingMessage()
  if (!streamingMsg) return 0

  // 粗略估算：基于已接收字符数
  // 实际场景中应由 LLM 服务提供 totalLength
  const receivedLength = streamingMsg.content.length
  const estimatedTotal = Math.max(receivedLength * 2, 100)  // 粗略估计
  return Math.min(receivedLength / estimatedTotal, 0.99)
}

// ============================================================
// 派生查询：角色统计（memoizeByRef 缓存）
// ============================================================

const ROLE_STAT_KEY: Record<MessageRole, keyof Omit<MessageStats, 'total'>> = {
  user: 'user',
  assistant: 'assistant',
  system: 'system',
}

/**
 * 各角色消息数统计
 * 性能优化：基于 messages 引用记忆化，单次遍历完成所有计数
 */
export const messageStatsMemo = memoizeByRef((messages: readonly ChatMessage[]): MessageStats => {
  const stats: MessageStats = {
    user: 0,
    assistant: 0,
    system: 0,
    total: messages.length,
  }
  for (const m of messages) {
    stats[ROLE_STAT_KEY[m.role]]++
  }
  return stats
}, 'messageStats')

/**
 * 获取消息统计（自动传入最新 messages）
 */
export function getMessageStats(): MessageStats {
  return messageStatsMemo(useChatStore.getState().messages)
}

/**
 * 按角色筛选消息
 */
export function messagesByRole(role: MessageRole): ChatMessage[] {
  return useChatStore.getState().messages.filter(m => m.role === role)
}

/**
 * 对话轮次（user-assistant 配对数）
 * 计算：user 消息数（每条 user 消息对应一轮对话）
 */
export function conversationTurns(): number {
  return getMessageStats().user
}

// ============================================================
// 派生查询：上下文管理
// ============================================================

/**
 * 估算 token 数（粗略：字符数/4）
 * 注意：此为粗略估算，实际 token 数需 tokenizer 计算
 */
export function estimatedTokenCount(): number {
  const messages = useChatStore.getState().messages
  let charCount = 0
  for (const m of messages) {
    charCount += m.content.length
  }
  return Math.ceil(charCount / 4)
}

/**
 * 是否超过上下文长度限制
 */
export function isOverContextLimit(maxTokens: number = 8000): boolean {
  return estimatedTokenCount() > maxTokens
}

/**
 * 需要截断的历史消息数（超出限制时）
 * 保留最近的消息，截断最早的消息
 */
export function messagesToTruncate(maxTokens: number = 8000): number {
  const messages = useChatStore.getState().messages
  let charCount = 0
  for (const m of messages) {
    charCount += m.content.length
  }
  const estimatedTokens = Math.ceil(charCount / 4)
  if (estimatedTokens <= maxTokens) return 0

  // 计算需要截断的消息数
  const overflowTokens = estimatedTokens - maxTokens
  const overflowChars = overflowTokens * 4

  let truncateCount = 0
  let charsTruncated = 0
  for (const m of messages) {
    if (charsTruncated >= overflowChars) break
    charsTruncated += m.content.length
    truncateCount++
  }

  return truncateCount
}

// ============================================================
// 派生查询：消息搜索
// ============================================================

/**
 * 搜索消息（按关键词）
 */
export function searchMessages(keyword: string): ChatMessage[] {
  if (!keyword.trim()) return []
  const lowerKeyword = keyword.toLowerCase()
  return useChatStore.getState().messages.filter(
    m => m.content.toLowerCase().includes(lowerKeyword)
  )
}

/**
 * 按日期筛选消息
 * @param date YYYY-MM-DD 格式
 */
export function messagesByDate(date: string): ChatMessage[] {
  return useChatStore.getState().messages.filter(m => {
    const msgDate = new Date(m.timestamp).toISOString().split('T')[0]
    return msgDate === date
  })
}

// ============================================================
// React Hook 形式派生（可选）
// ============================================================

/**
 * Hook：订阅是否可发送
 */
export function useCanSend(): boolean {
  return useChatStore(state => !state.isStreaming && state.error === null)
}

/**
 * Hook：订阅最后一条消息
 */
export function useLastMessage(): ChatMessage | null {
  const messages = useChatStore(state => state.messages)
  if (messages.length === 0) return null
  return messages[messages.length - 1]!
}

/**
 * Hook：订阅消息统计
 */
export function useMessageStats(): MessageStats {
  const messages = useChatStore(state => state.messages)
  return messageStatsMemo(messages)
}

/**
 * Hook：订阅是否为空
 */
export function useIsEmpty(): boolean {
  return useChatStore(state => state.messages.length === 0)
}

/**
 * @module collectionRuntimeStore
 * @description 采集运行时状态管理。
 *
 * 订阅 `COLLECTION_EVENTS` 生命周期事件，维护链路追踪、实时日志、
 * 任务进度和质量指标快照，供可视化组件消费。
 *
 * @dataflow
 * - 执行者：collectionPipeline / fetcherService → eventBus.emit(COLLECTION_EVENTS.*)
 * - 本 Store：订阅事件 → 更新 traceSpans / logs / taskStatuses / stats
 * - 展示者：CollectTask/index.tsx / DataTestPanel.tsx / FetcherConfigPage.tsx / HomePage.tsx
 *
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-076, V9-DOC-DATA-075, V9-DOC-DATA-073]
*/

import { create } from 'zustand'
import { eventBus } from '@/lib/eventBus'
import { getLogger } from '@/lib/logger'
import { COLLECTION_EVENTS } from '@/types/modules/collection.types'
import type {
  CollectionLifecycleEvent,
  CollectionTraceSpan,
  CollectionTaskRuntime,
  CollectionLog,
} from '@/types/modules/collection.types'
import { getQualitySnapshot, type QualityMetrics } from '@/services/data-collector/qualityMetricsCollector'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { queryTraceRecords } from '@/services/data-collector/tracePersistenceService'

const logger = getLogger()

// ============================================================
// 状态定义
// ============================================================

interface CollectionRuntimeState {
  /** 链路追踪映射（traceId → span） */
  traceSpans: Record<string, CollectionTraceSpan>
  /** 按时间排序的实时日志 */
  logs: CollectionLog[]
  /** 任务状态映射（taskId → runtime） */
  taskStatuses: Record<string, CollectionTaskRuntime>
  /** 全局进度（0-100） */
  overallProgress: number
  /** 质量指标快照 */
  stats: QualityMetrics
  /** 是否正在运行批量任务 */
  isRunning: boolean

  // Actions
  appendLog: (log: CollectionLog) => void
  addOrUpdateSpan: (span: CollectionTraceSpan) => void
  updateTaskStatus: (taskId: string, update: Partial<CollectionTaskRuntime> & { taskId: string }) => void
  setOverallProgress: (progress: number) => void
  refreshStats: () => void
  setRunning: (running: boolean) => void
  clearLogs: () => void
  clearTraces: () => void
  loadPersistedTraces: () => Promise<void>
  reset: () => void
}

// ============================================================
// 辅助函数
// ============================================================

const MAX_LOGS = 200

function formatTime(timestamp: number): string {
  const date = new Date(timestamp)
  return date.toLocaleTimeString('zh-CN', { hour12: false })
}

function mapEventLevel(type: CollectionLifecycleEvent['type']): CollectionLog['level'] {
  switch (type) {
    case COLLECTION_EVENTS.SOURCE_FAIL:
    case COLLECTION_EVENTS.WRITE_FAIL:
      return 'error'
    case COLLECTION_EVENTS.FALLBACK:
      return 'warn'
    case COLLECTION_EVENTS.SOURCE_SUCCESS:
    case COLLECTION_EVENTS.WRITE_SUCCESS:
    case COLLECTION_EVENTS.COMPLETE:
      return 'success'
    default:
      return 'info'
  }
}

function createInitialStats(): QualityMetrics {
  return {
    since: Date.now(),
    totalCollects: 0,
    successCollects: 0,
    successRate: 0,
    mockCollects: 0,
    mockSuccesses: 0,
    realSuccessRate: 0,
    completeness: 0,
    sourceCounts: { tushare: 0, tencent: 0, sina: 0, netease: 0, akshare: 0, mock: 0 },
    fallbackCount: 0,
    writeSuccess: 0,
    writeTotal: 0,
    writeRate: 0,
    mockWrites: 0,
    avgLatency: 0,
    totalLatency: 0,
  }
}

// ============================================================
// Store
// ============================================================

const initialState = {
  traceSpans: {} as Record<string, CollectionTraceSpan>,
  logs: [] as CollectionLog[],
  taskStatuses: {} as Record<string, CollectionTaskRuntime>,
  overallProgress: 0,
  stats: createInitialStats(),
  isRunning: false,
}

/**
 * useCollectionRuntimeStore
 */
export const useCollectionRuntimeStore = create<CollectionRuntimeState>((set) => ({
  ...initialState,

  appendLog: (log) => {
    set((state) => {
      const logs = [log, ...state.logs].slice(0, MAX_LOGS)
      return { logs }
    })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'appendLog' })
  },

  addOrUpdateSpan: (span) => {
    set((state) => ({
      traceSpans: { ...state.traceSpans, [span.traceId]: span },
    }))
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'updateSpan', traceId: span.traceId })
  },

  updateTaskStatus: (taskId, update) => {
    set((state) => {
      const existing = state.taskStatuses[taskId]
      const next: CollectionTaskRuntime = {
        dimensionCode: existing?.dimensionCode ?? update.dimensionCode ?? '',
        symbol: existing?.symbol ?? update.symbol ?? '',
        status: existing?.status ?? 'pending',
        progress: existing?.progress ?? 0,
        ...existing,
        ...update,
        taskId,
      }
      return { taskStatuses: { ...state.taskStatuses, [taskId]: next } }
    })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'updateTaskStatus', taskId })
  },

  setOverallProgress: (overallProgress) => {
    set({ overallProgress })
  },

  refreshStats: () => {
    set({ stats: getQualitySnapshot() })
  },

  setRunning: (isRunning) => {
    set({ isRunning })
  },

  clearLogs: () => {
    set({ logs: [] })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'clearLogs' })
  },

  clearTraces: () => {
    set({ traceSpans: {} })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'clearTraces' })
  },

  loadPersistedTraces: async () => {
    try {
      const spans = await queryTraceRecords({ limit: 500 })
      set((state) => {
        const merged = { ...state.traceSpans }
        const rehydratedTasks: Record<string, CollectionTaskRuntime> = { ...state.taskStatuses }

        for (const span of spans) {
          // 合并 span，不覆盖内存中已有更新版本
          if (!merged[span.traceId]) {
            merged[span.traceId] = span
          }

          // 从 span 重建 taskStatuses（只填充内存中尚不存在的任务）
          if (span.taskId && !rehydratedTasks[span.taskId]) {
            const status: CollectionTaskRuntime['status'] =
              span.result === 'success'
                ? 'completed'
                : span.result === 'partial'
                  ? 'completed'
                  : 'error'

            rehydratedTasks[span.taskId] = {
              taskId: span.taskId,
              dimensionCode: span.dimensionCode,
              symbol: span.symbol,
              status,
              progress: span.result === 'success' || span.result === 'partial' ? 100 : 0,
              startedAt: span.startedAt,
              completedAt: span.completedAt,
              error: span.error,
            }
          }
        }

        return { traceSpans: merged, taskStatuses: rehydratedTasks }
      })
      logger.info('[collectionRuntimeStore] 已加载持久化 traces + 重建任务状态', { count: spans.length })
    } catch (err) {
      logger.error('[collectionRuntimeStore] 加载持久化 traces 失败', { error: err })
    }
  },

  reset: () => {
    set(initialState)
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'reset' })
  },
}))

// ============================================================
// 事件订阅
// ============================================================

function handleLifecycleEvent(event: CollectionLifecycleEvent): void {
  const store = useCollectionRuntimeStore.getState()

  // 刷新质量指标快照
  store.refreshStats()

  // 记录日志
  store.appendLog({
    id: `${event.traceId}-${event.timestamp}`,
    timestamp: event.timestamp,
    time: formatTime(event.timestamp),
    level: mapEventLevel(event.type),
    dimensionCode: event.dimensionCode,
    symbol: event.symbol,
    sourceId: event.sourceId,
    message: event.message,
    traceId: event.traceId,
  })

  // 更新任务状态
  if (event.taskId) {
    const payload = event.payload
    const progress = typeof payload?.progress === 'number' ? payload.progress : undefined
    const statusFromPayload = typeof payload?.status === 'string' ? payload.status : undefined
    const status: CollectionTaskRuntime['status'] =
      statusFromPayload === 'running'
        ? 'running'
        : statusFromPayload === 'completed'
          ? 'completed'
          : statusFromPayload === 'error'
            ? 'error'
            : statusFromPayload === 'paused'
              ? 'paused'
              : 'pending'

    store.updateTaskStatus(event.taskId, {
      taskId: event.taskId,
      dimensionCode: event.dimensionCode,
      symbol: event.symbol,
      status,
      progress,
    })
  }

  // 更新 trace span（当事件携带完整 span 时）
  if (event.type === COLLECTION_EVENTS.COMPLETE && event.payload && typeof event.payload === 'object') {
    const span = event.payload.span as CollectionTraceSpan | undefined
    if (span) {
      store.addOrUpdateSpan(span)
    }
  }

  // 更新全局进度
  if (event.type === COLLECTION_EVENTS.TASK_STATUS) {
    const payload = event.payload
    if (typeof payload?.progress === 'number') {
      store.setOverallProgress(payload.progress)
    }
  }
}

function handleTraceSpan(span: CollectionTraceSpan): void {
  const store = useCollectionRuntimeStore.getState()
  store.addOrUpdateSpan(span)
}

// 全局订阅（store 生命周期与页面共存，跨 Tab 通过 withBroadcast 同步）
Object.values(COLLECTION_EVENTS).forEach((eventName) => {
  eventBus.on(eventName, (event) => {
    try {
      handleLifecycleEvent(event as CollectionLifecycleEvent)
    } catch (err) {
      logger.error('[collectionRuntimeStore] 生命周期事件处理失败', { error: err, event })
    }
  })
})

eventBus.on('collect:trace', (span) => {
  try {
    handleTraceSpan(span as CollectionTraceSpan)
  } catch (err) {
    logger.error('[collectionRuntimeStore] trace 处理失败', { error: err, span })
  }
})

// 启动时加载历史 trace（浏览器环境）
if (typeof window !== 'undefined') {
  void useCollectionRuntimeStore.getState().loadPersistedTraces()
}

logger.info('[collectionRuntimeStore] 已订阅采集生命周期事件')

/**
 * @module collectionWizardStore
 * @description 数据采集向导状态管理（核心）
 *
 * 管理 4 步向导式数据采集流程的状态：
 * 1. 数据源配置
 * 2. 采集策略
 * 3. 任务预览
 * 4. 执行监控
 *
 * v1.2 拆分（2026-07-15）：
 * - 持久化相关 actions 抽离至 `collectionWizardStore.persistence.ts`
 * - MOCK 配置数据抽离至 `collectionWizardStore.mock.ts`
 * - 工具函数抽离至 `collectionWizardStore.utils.ts`
 * - 派生查询抽离至 `collectionWizardStore.derived.ts`
 *
 * v1.1 增强（2026-07-15）：
 * - 链路追踪 ID（traceId），关联同一任务的所有日志
 * - 阶段标识（stage），标记采集生命周期阶段
 * - 耗时记录（durationMs），记录每个阶段的执行时间
 * - 配置持久化集成（saveAsTemplate 时自动保存到 IndexedDB）
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-076, V9-DOC-DATA-075, V9-DOC-DATA-073]
*/

import { create } from 'zustand'
import { withBroadcast } from '@/lib/withBroadcast'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import type {
  CollectionWizardStep,
  CollectionFrequency,
  CollectionPriority,
  CollectionCacheStrategy,
  ApiConfig,
  DimensionProgress,
  WizardLogEntry,
  CollectionWizardState,
  PersistedWizardConfig,
} from '@/types/modules/collection.types'
import { saveWizardConfig } from '@/services/collection/collectionWizardPersistence'
import { generateTraceId, formatDuration } from './collectionWizardStore.utils'
import { createPersistenceActions } from './collectionWizardStore.persistence'

const logger = getLogger()

/** 广播向导状态变更 */
const broadcastWizard = (action: string, payload?: Record<string, unknown>): void => {
  withBroadcast(EVENT_NAMES.COLLECTION_WIZARD_CHANGED, { action, ...payload })
}

// ============================================================
// 状态定义
// ============================================================

const INITIAL_STATE = {
  currentStep: 1 as CollectionWizardStep,
  isOpen: false,
  selectedDimensions: [] as string[],
  apiConfigs: {} as Record<string, ApiConfig>,
  frequency: 'daily' as CollectionFrequency,
  cronExpression: '0 0 * * *',
  priority: 'medium' as CollectionPriority,
  cacheTTL: 3600,
  cacheStrategy: 'stale-while-revalidate' as CollectionCacheStrategy,
  taskName: '',
  saveAsTemplate: false,
  taskId: null as string | null,
  taskStatus: 'idle' as CollectionWizardState['taskStatus'],
  dimensionProgress: [] as DimensionProgress[],
  logs: [] as WizardLogEntry[],
  /** 当前任务的链路追踪 ID */
  traceId: null as string | null,
  /** 已保存的配置模板列表（开发阶段使用 mock 数据） */
  // 初始为空数组；首次访问时从 DB 加载真实配置（见 loadSavedConfigs action）
  savedConfigs: [] as PersistedWizardConfig[],
  /** 是否正在保存配置 */
  isSavingConfig: false,
}

// ============================================================
// Actions 接口
// ============================================================

interface CollectionWizardActions {
  // 步骤控制
  setStep: (step: CollectionWizardStep) => void
  openWizard: () => void
  closeWizard: () => void
  resetWizard: () => void

  // 步骤1：数据源配置
  toggleDimension: (code: string, checked: boolean) => void
  updateApiConfig: (code: string, config: ApiConfig) => void

  // 步骤2：采集策略
  setFrequency: (frequency: CollectionFrequency) => void
  setCronExpression: (cron: string) => void
  setPriority: (priority: CollectionPriority) => void
  setCacheTTL: (ttl: number) => void
  setCacheStrategy: (strategy: CollectionCacheStrategy) => void
  setTaskName: (name: string) => void
  setSaveAsTemplate: (save: boolean) => void

  // 任务生命周期
  startTask: () => Promise<void>
  pauseTask: () => void
  resumeTask: () => void
  stopTask: () => void

  // 日志与进度
  addLog: (log: Omit<WizardLogEntry, 'id' | 'timestamp'>) => void
  updateDimensionProgress: (code: string, update: Partial<DimensionProgress>) => void
}

type CollectionWizardStore = typeof INITIAL_STATE &
  CollectionWizardActions &
  // 持久化 actions 通过 mixin 合并
  Pick<
    ReturnType<typeof createPersistenceActions>,
    keyof ReturnType<typeof createPersistenceActions>
  >

// ============================================================
// Store 实现
// ============================================================

/**
 * useCollectionWizardStore
 */
export const useCollectionWizardStore = create<CollectionWizardStore>()((set, get, store) => ({
  ...INITIAL_STATE,

  // 合并持久化 actions
  ...createPersistenceActions(set, get, store),

  // ─────────── 步骤控制 ───────────
  setStep: (step: CollectionWizardStep) => {
    const { currentStep } = get()
    logger.info('[CollectionWizardStore] setStep', {
      from: currentStep,
      to: step,
      traceId: get().traceId,
    })
    set({ currentStep: step })
    broadcastWizard('setStep', { from: currentStep, to: step })
  },

  openWizard: () => {
    logger.info('[CollectionWizardStore] openWizard', {
      previousTaskId: get().taskId,
      previousStatus: get().taskStatus,
    })
    set({ isOpen: true })
    broadcastWizard('openWizard')
    // 打开时自动加载已保存的配置模板
    void get().loadSavedConfigs()
  },

  closeWizard: () => {
    logger.info('[CollectionWizardStore] closeWizard', {
      taskId: get().taskId,
      taskStatus: get().taskStatus,
      logCount: get().logs.length,
    })
    set({ isOpen: false })
    broadcastWizard('closeWizard')
  },

  resetWizard: () => {
    const { taskId, logs, traceId, savedConfigs } = get()
    logger.info('[CollectionWizardStore] resetWizard', {
      taskId,
      traceId,
      logCount: logs.length,
    })
    set({ ...INITIAL_STATE, savedConfigs })
    broadcastWizard('resetWizard')
  },

  // ─────────── 步骤1：数据源配置 ───────────
  toggleDimension: (code: string, checked: boolean) => {
    const { selectedDimensions } = get()
    const newDimensions = checked
      ? [...selectedDimensions, code]
      : selectedDimensions.filter((d) => d !== code)
    logger.info('[CollectionWizardStore] toggleDimension', {
      code,
      checked,
      beforeCount: selectedDimensions.length,
      afterCount: newDimensions.length,
      newDimensions,
    })
    set({ selectedDimensions: newDimensions })
    broadcastWizard('toggleDimension', { code, checked })
  },

  updateApiConfig: (code: string, config: ApiConfig) => {
    const { apiConfigs } = get()
    const previous = apiConfigs[code]
    logger.info('[CollectionWizardStore] updateApiConfig', {
      code,
      previous: previous !== undefined ? previous : null,
      updated: config,
    })
    set({ apiConfigs: { ...apiConfigs, [code]: config } })
    broadcastWizard('updateApiConfig', { code, config })
  },

  // ─────────── 步骤2：采集策略 ───────────
  setFrequency: (frequency: CollectionFrequency) => {
    const { frequency: prev } = get()
    logger.info('[CollectionWizardStore] setFrequency', { from: prev, to: frequency })
    set({ frequency })
    broadcastWizard('setFrequency', { from: prev, to: frequency })
  },

  setCronExpression: (cron: string) => {
    const { cronExpression: prev } = get()
    logger.info('[CollectionWizardStore] setCronExpression', { from: prev, to: cron })
    set({ cronExpression: cron })
    broadcastWizard('setCronExpression', { from: prev, to: cron })
  },

  setPriority: (priority: CollectionPriority) => {
    const { priority: prev } = get()
    logger.info('[CollectionWizardStore] setPriority', { from: prev, to: priority })
    set({ priority })
    broadcastWizard('setPriority', { from: prev, to: priority })
  },

  setCacheTTL: (ttl: number) => {
    const { cacheTTL: prev } = get()
    logger.info('[CollectionWizardStore] setCacheTTL', { from: prev, to: ttl })
    set({ cacheTTL: ttl })
    broadcastWizard('setCacheTTL', { from: prev, to: ttl })
  },

  setCacheStrategy: (strategy: CollectionCacheStrategy) => {
    const { cacheStrategy: prev } = get()
    logger.info('[CollectionWizardStore] setCacheStrategy', { from: prev, to: strategy })
    set({ cacheStrategy: strategy })
    broadcastWizard('setCacheStrategy', { from: prev, to: strategy })
  },

  setTaskName: (name: string) => {
    logger.info('[CollectionWizardStore] setTaskName', { name })
    set({ taskName: name })
    broadcastWizard('setTaskName', { name })
  },

  setSaveAsTemplate: (save: boolean) => {
    logger.info('[CollectionWizardStore] setSaveAsTemplate', { save })
    set({ saveAsTemplate: save })
    broadcastWizard('setSaveAsTemplate', { save })
  },

  // ─────────── 任务生命周期 ───────────
  startTask: async () => {
    const state = get()
    const { selectedDimensions, taskName, saveAsTemplate } = state
    const traceId = generateTraceId()
    const taskStartTime = Date.now()

    logger.info('[CollectionWizardStore] startTask - 初始化', {
      traceId,
      taskName,
      dimensions: selectedDimensions,
      dimensionCount: selectedDimensions.length,
      frequency: state.frequency,
      priority: state.priority,
      cacheStrategy: state.cacheStrategy,
      cacheTTL: state.cacheTTL,
      saveAsTemplate,
    })

    // 如果选择了保存为模板，先持久化配置
    if (saveAsTemplate) {
      logger.info('[CollectionWizardStore] startTask - 保存配置模板', { traceId })
      set({ isSavingConfig: true })
      try {
        await saveWizardConfig({
          name: taskName || `配置_${new Date().toLocaleDateString('zh-CN')}`,
          selectedDimensions,
          apiConfigs: state.apiConfigs,
          frequency: state.frequency,
          cronExpression: state.cronExpression,
          priority: state.priority,
          cacheTTL: state.cacheTTL,
          cacheStrategy: state.cacheStrategy,
          saveAsTemplate: true,
        })
        logger.info('[CollectionWizardStore] startTask - 配置模板保存成功', { traceId })
        // 刷新模板列表
        await get().loadSavedConfigs()
      } catch (error) {
        logger.error('[CollectionWizardStore] startTask - 配置模板保存失败', {
          traceId,
          error: error instanceof Error ? error.message : String(error),
        })
        // 保存失败不阻断任务执行
      }
      set({ isSavingConfig: false })
    }

    set({
      traceId,
      taskId: `task_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
      taskStatus: 'running',
      logs: [],
      dimensionProgress: selectedDimensions.map((code: string) => ({
        dimensionCode: code,
        dimensionName: code,
        progress: 0,
        status: 'pending',
      })),
    })

    get().addLog({
      level: 'info',
      message: `任务 ${taskName !== '' ? taskName : '未命名'} 已启动`,
      traceId,
      stage: 'task:start',
    })

    get().addLog({
      level: 'info',
      message: `配置: 维度×${selectedDimensions.length} | 频率=${state.frequency} | 优先级=${state.priority} | 缓存=${state.cacheStrategy}(${state.cacheTTL}s)`,
      traceId,
      stage: 'task:config',
    })

    // 模拟采集进度（带详细阶段日志）
    const simulateProgress = async () => {
      for (const dim of selectedDimensions) {
        const dimStartTime = Date.now()

        // 阶段1: 开始采集
        get().updateDimensionProgress(dim, { status: 'running', progress: 0 })
        get().addLog({
          level: 'info',
          message: `[${dim}] 开始采集 - source:start`,
          dimensionCode: dim,
          traceId,
          stage: 'source:start',
        })

        // 阶段2: 模拟数据拉取
        await new Promise((resolve) => setTimeout(resolve, 300))
        const fetchDuration = Date.now() - dimStartTime
        get().addLog({
          level: 'info',
          message: `[${dim}] 数据拉取完成 - source:success (${formatDuration(fetchDuration)})`,
          dimensionCode: dim,
          traceId,
          stage: 'source:success',
          durationMs: fetchDuration,
        })

        // 阶段3: 模拟数据转换
        get().addLog({
          level: 'info',
          message: `[${dim}] 数据转换中 - transform`,
          dimensionCode: dim,
          traceId,
          stage: 'transform',
        })
        await new Promise((resolve) => setTimeout(resolve, 200))

        // 阶段4: 模拟写入
        const writeStartTime = Date.now()
        get().addLog({
          level: 'info',
          message: `[${dim}] 写入存储 - write:start`,
          dimensionCode: dim,
          traceId,
          stage: 'write:start',
        })

        // 模拟进度
        for (let i = 20; i <= 100; i += 20) {
          await new Promise((resolve) => setTimeout(resolve, 300))
          get().updateDimensionProgress(dim, { progress: i })
        }

        const writeDuration = Date.now() - writeStartTime
        get().addLog({
          level: 'info',
          message: `[${dim}] 写入完成 - write:success (${formatDuration(writeDuration)})`,
          dimensionCode: dim,
          traceId,
          stage: 'write:success',
          durationMs: writeDuration,
        })

        // 阶段5: 维度完成
        const totalDimDuration = Date.now() - dimStartTime
        get().updateDimensionProgress(dim, { status: 'completed', progress: 100 })
        get().addLog({
          level: 'success',
          message: `[${dim}] 维度采集完成 - complete (总耗时 ${formatDuration(totalDimDuration)})`,
          dimensionCode: dim,
          traceId,
          stage: 'complete',
          durationMs: totalDimDuration,
        })
      }

      // 任务完成
      const totalDuration = Date.now() - taskStartTime
      set({ taskStatus: 'completed' })
      get().addLog({
        level: 'success',
        message: `所有维度采集完成 - 总耗时 ${formatDuration(totalDuration)}`,
        traceId,
        stage: 'task:complete',
        durationMs: totalDuration,
      })
    }

    void simulateProgress()
  },

  pauseTask: () => {
    const { taskId, taskStatus } = get()
    logger.info('[CollectionWizardStore] pauseTask', { taskId, fromStatus: taskStatus })
    set({ taskStatus: 'paused' })
    get().addLog({
      level: 'warn',
      message: '任务已暂停 - task:pause',
      traceId: get().traceId ?? undefined,
      stage: 'task:pause',
    })
    broadcastWizard('pauseTask', { taskId })
  },

  resumeTask: () => {
    const { taskId } = get()
    logger.info('[CollectionWizardStore] resumeTask', { taskId })
    set({ taskStatus: 'running' })
    get().addLog({
      level: 'info',
      message: '任务已恢复 - task:resume',
      traceId: get().traceId ?? undefined,
      stage: 'task:resume',
    })
    broadcastWizard('resumeTask', { taskId })
  },

  stopTask: () => {
    const { taskId, logs } = get()
    logger.info('[CollectionWizardStore] stopTask', {
      taskId,
      logCount: logs.length,
    })
    set({ taskStatus: 'failed' })
    get().addLog({
      level: 'error',
      message: '任务已停止 - task:abort',
      traceId: get().traceId ?? undefined,
      stage: 'task:abort',
    })
    broadcastWizard('stopTask', { taskId })
  },

  // ─────────── 日志与进度 ───────────
  addLog: (log: Omit<WizardLogEntry, 'id' | 'timestamp'>) => {
    const entry: WizardLogEntry = {
      ...log,
      id: `log_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`,
      timestamp: Date.now(),
    }
    set((state) => ({ logs: [...state.logs, entry] }))
  },

  updateDimensionProgress: (code: string, update: Partial<DimensionProgress>) => {
    set((state) => ({
      dimensionProgress: state.dimensionProgress.map((d) =>
        d.dimensionCode === code ? { ...d, ...update } : d,
      ),
    }))
  },
}))

