// ============================================================
// 类型定义
// ============================================================

interface ExecutionState {
  // ---- 核心数据 ----
  /** 全部执行计划 */
  plans: ExecutionPlan[]
  /** 活跃计划：phase in [plan, confirmed, pending] */
  activePlans: ExecutionPlan[]

  // ---- 加载状态 ----
  /** 是否正在处理（执行中） */
