/**
 * @module researchPoolStore
 * @description 研究精选池 Zustand Store。
 *
 * 物理数据仍存储于 IndexedDB `stocks` store，通过 `pool === 'research'` 过滤。
  * @doc [V9-DOC-PROJ-108, V9-DOC-BACK-011, V9-DOC-DATA-024, V9-DOC-DATA-032, V9-DOC-DATA-031]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import {
  DATA_SOURCE,
  ENVELOPE_ACTION,
  ENVELOPE_TARGET,
  MODULE_ID,
  STORE_NAME,
} from '@/config/dbConfig'
import {
  DEFAULT_POOL_GROUP,
  POOL_TYPE,
  RESEARCH_STATUS,
  type PoolType,
  type ResearchStatus,
} from '@/constants/pool.constants'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { isValidTransition } from '@/core/poolTransitionEngine'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import type { PoolItem, ResearchPoolItem } from '@/types/modules/pool.types'
import type { Stock } from '@/data/types'

import { nanoid } from 'nanoid'

const logger = getLogger()
const POOL: PoolType = POOL_TYPE.research

interface ResearchPoolState {
  items: PoolItem[]
  loading: boolean
  error: string | null
  isRefreshing: boolean
  lastUpdated: number

  refresh: () => Promise<void>
  addItem: (
    item: Omit<ResearchPoolItem, 'pool' | 'status' | 'dataVersion' | 'ingestedAt' | 'updatedAt'>,
  ) => Promise<boolean>
  updateItem: (symbol: string, updates: Partial<ResearchPoolItem>) => Promise<boolean>
  deleteItem: (symbol: string) => Promise<boolean>
  updateStatus: (symbol: string, newStatus: ResearchStatus) => Promise<boolean>
  updateGroup: (symbol: string, group: string) => Promise<boolean>
  getByStatus: (status: ResearchStatus) => PoolItem[]
  getByGroup: (group: string) => PoolItem[]
}

const initialState = {
  items: [] as PoolItem[],
  loading: false,
  error: null as string | null,
  isRefreshing: false,
  lastUpdated: 0,
}

function toPoolItem(stock: Stock): PoolItem {
  return {
    symbol: stock.symbol,
    name: stock.name,
    pool: stock.pool,
    status: stock.researchStatus,
    price: stock.price,
    pe: stock.pe,
    pb: stock.pb,
    roe: stock.roe,
    marketCap: stock.marketCap,
    source: stock.source,
    dataVersion: stock.dataVersion,
    dataQuality: stock.dataQuality,
    ingestedAt: stock.ingestedAt,
    updatedAt: stock.updatedAt,
    industryCode: stock.industryCode,
    theme: stock.theme,
    sector: stock.sector,
    group: stock.group,
    researchNote: stock.sector,
  } as PoolItem
}

/**
 * useResearchPoolStore
 */
export const useResearchPoolStore = create<ResearchPoolState>((set, get) => ({
  ...initialState,

  refresh: async () => {
    if (get().isRefreshing) return
    const isFirstLoad = get().items.length === 0 && get().lastUpdated === 0
    logger.info(`[researchPoolStore] refresh 开始`)
    set({ isRefreshing: true, loading: isFirstLoad, error: null })

    try {
      const result = await dataBridge.query<Stock[]>({
        action: ENVELOPE_ACTION.queryByIndex,
        store: STORE_NAME.stocks,
        indexName: 'by-pool',
        indexValue: POOL,
        source: MODULE_ID.pool,
      })
      if (!result.success) {
        throw new Error(result.error ?? '查询研究池失败')
      }
      const list = (result.data ?? [])
        .filter((s) => s.pool === POOL)
        .map(toPoolItem)
      set({
        items: list,
        loading: false,
        isRefreshing: false,
        lastUpdated: Date.now(),
        error: null,
      })
      logger.info(`[researchPoolStore] refresh 完成: ${list.length} 条`)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] refresh 失败: ${message}`)
      set({ error: message, loading: false, isRefreshing: false })
    }
  },

  addItem: async (item) => {
    const normalizedSymbol = item.symbol.trim().toUpperCase()
    logger.info(`[researchPoolStore] addItem: ${item.name}(${normalizedSymbol})`)
    set({ error: null })

    try {
      const existingResult = await dataBridge.query<Stock>({
        action: ENVELOPE_ACTION.queryGet,
        store: STORE_NAME.stocks,
        key: normalizedSymbol,
        source: MODULE_ID.pool,
      })
      if (existingResult.success && existingResult.data) {
        const message = `${item.name}(${normalizedSymbol}) 已存在`
        logger.warn(`[researchPoolStore] addItem 失败: ${message}`)
        set({ error: message })
        return false
      }

      const fullStock: Stock = {
        ...item,
        symbol: normalizedSymbol,
        pool: POOL,
        researchStatus: RESEARCH_STATUS.candidate,
        source: item.source ?? DATA_SOURCE.manual,
        group: item.group ?? DEFAULT_POOL_GROUP,
        dataVersion: 1,
        ingestedAt: Date.now(),
        updatedAt: Date.now(),
      }

      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.pool,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.insertStock,
          traceId: `pool-research-add-${nanoid(8)}-${normalizedSymbol}`,
        },
        fullStock,
      )
      await dataBridge.forward(envelope)
      withBroadcast(EVENT_NAMES.POOL_CHANGED, { action: 'add', pool: POOL, symbol: normalizedSymbol })
      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] addItem 失败: ${message}`)
      set({ error: message })
      return false
    }
  },

  updateItem: async (symbol, updates) => {
    const normalized = symbol.trim().toUpperCase()
    logger.info(`[researchPoolStore] updateItem: ${normalized}`)
    set({ error: null })

    const existing = get().items.find((s) => s.symbol === normalized)
    if (!existing) {
      const message = `标的不存在: ${normalized}`
      logger.warn(`[researchPoolStore] updateItem 失败: ${message}`)
      set({ error: message })
      return false
    }

    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.pool,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.updateStock,
          traceId: `pool-research-update-${nanoid(8)}-${normalized}`,
        },
        { symbol: normalized, ...updates, updatedAt: Date.now() },
      )
      await dataBridge.forward(envelope)
      withBroadcast(EVENT_NAMES.POOL_CHANGED, { action: 'update', pool: POOL, symbol: normalized, updates })
      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] updateItem 失败: ${message}`)
      set({ error: message })
      return false
    }
  },

  deleteItem: async (symbol) => {
    const normalized = symbol.trim().toUpperCase()
    logger.info(`[researchPoolStore] deleteItem: ${normalized}`)
    set({ error: null })

    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.pool,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.deleteStock,
          traceId: `pool-research-delete-${nanoid(8)}-${normalized}`,
        },
        { symbol: normalized },
      )
      await dataBridge.forward(envelope)
      withBroadcast(EVENT_NAMES.POOL_CHANGED, { action: 'delete', pool: POOL, symbol: normalized })
      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] deleteItem 失败: ${message}`)
      set({ error: message })
      return false
    }
  },

  updateStatus: async (symbol, newStatus) => {
    const normalized = symbol.trim().toUpperCase()
    logger.info(`[researchPoolStore] updateStatus: ${normalized} → ${newStatus}`)
    set({ error: null })

    const item = get().items.find((s) => s.symbol === normalized)
    if (!item) {
      const message = `标的不存在: ${normalized}`
      logger.warn(`[researchPoolStore] updateStatus 失败: ${message}`)
      set({ error: message })
      return false
    }

    if (!isValidTransition(item.pool, item.status, POOL, newStatus)) {
      const message = `非法状态流转: ${item.status} → ${newStatus}`
      logger.warn(`[researchPoolStore] updateStatus 失败: ${message}`)
      set({ error: message })
      return false
    }

    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.pool,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.updateStock,
          traceId: `pool-research-status-${nanoid(8)}-${normalized}`,
        },
        { symbol: normalized, researchStatus: newStatus, updatedAt: Date.now() },
      )
      await dataBridge.forward(envelope)
      withBroadcast(EVENT_NAMES.POOL_CHANGED, { action: 'updateStatus', pool: POOL, symbol: normalized, newStatus })
      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] updateStatus 失败: ${message}`)
      set({ error: message })
      return false
    }
  },

  updateGroup: async (symbol, group) => {
    const normalized = symbol.trim().toUpperCase()
    const normalizedGroup = group.trim()
    logger.info(`[researchPoolStore] updateGroup: ${normalized} → ${normalizedGroup}`)
    set({ error: null })

    if (!normalizedGroup) {
      const message = '分组名称不能为空'
      logger.warn(`[researchPoolStore] updateGroup 失败: ${message}`)
      set({ error: message })
      return false
    }

    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.pool,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.updateStock,
          traceId: `pool-research-group-${nanoid(8)}-${normalized}`,
        },
        { symbol: normalized, group: normalizedGroup, updatedAt: Date.now() },
      )
      await dataBridge.forward(envelope)
      withBroadcast(EVENT_NAMES.POOL_CHANGED, { action: 'updateGroup', pool: POOL, symbol: normalized, group: normalizedGroup })
      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[researchPoolStore] updateGroup 失败: ${message}`)
      set({ error: message })
      return false
    }
  },

  getByStatus: (status) => {
    return get().items.filter((s) => s.status === status)
  },

  getByGroup: (group) => {
    return get().items.filter((s) => (s.group ?? DEFAULT_POOL_GROUP) === group)
  },
}))

/**
 * getResearchPoolTotalCount
 * @returns number
 */
export function getResearchPoolTotalCount(): number {
  return useResearchPoolStore.getState().items.length
}

/**
 * getResearchPoolItemBySymbol
 * @param symbol
 * @returns PoolItem | undefined
 */
export function getResearchPoolItemBySymbol(symbol: string): PoolItem | undefined {
  return useResearchPoolStore.getState().items.find((s) => s.symbol === symbol)
}

/**
 * getResearchPoolGroups
 * @returns string[]
 */
export function getResearchPoolGroups(): string[] {
  const { items } = useResearchPoolStore.getState()
  const groups = new Set<string>()
  for (const item of items) {
    groups.add(item.group ?? DEFAULT_POOL_GROUP)
  }
  return Array.from(groups).sort()
}

let _unsubscribe: (() => void) | null = null
let _debounceTimer: ReturnType<typeof setTimeout> | null = null
const DEBOUNCE_MS = 100

function debouncedRefresh(): void {
  if (_debounceTimer) clearTimeout(_debounceTimer)
  _debounceTimer = setTimeout(() => {
    _debounceTimer = null
    logger.debug('[researchPoolStore] 去抖触发 refresh')
    void useResearchPoolStore.getState().refresh()
  }, DEBOUNCE_MS)
}

/**
 * initResearchPoolStoreSubscriptions
 */
export function initResearchPoolStoreSubscriptions(): () => void {
  if (_unsubscribe) {
    logger.warn('[researchPoolStore] Subscriptions already initialized, skipping')
    return () => destroyResearchPoolStoreSubscriptions()
  }

  logger.info('[researchPoolStore] 初始化 DataBridge stocks 频道订阅')

  _unsubscribe = dataBridge.subscribe(STORE_NAME.stocks, (envelope) => {
    if (envelope.meta.source === MODULE_ID.pool) return
    debouncedRefresh()
  })

  return () => destroyResearchPoolStoreSubscriptions()
}

function destroyResearchPoolStoreSubscriptions(): void {
  _unsubscribe?.()
  _unsubscribe = null
  if (_debounceTimer) {
    clearTimeout(_debounceTimer)
    _debounceTimer = null
  }
  logger.info('[researchPoolStore] 订阅已销毁')
}

/**
 * 测试用：重置订阅状态
 */
export function _resetResearchPoolStoreSubscriptionsForTest(): void {
  destroyResearchPoolStoreSubscriptions()
  logger.info('[researchPoolStore] 订阅已重置（测试）')
}

/**
 * @module rotationSignalStore.derived
 * @description rotationSignalStore 派生查询函数集合
 *
 * 设计原则：
 *   1. 纯函数：通过 useRotationSignalStore.getState() 访问状态
 *   2. 性能优化：memoizeByRef 缓存无参数派生（signals 引用未变时直接返回缓存）
 *   3. 派生不调用派生：sectorStats 直接遍历 signals，避免调用 signalsByStrength
 *   4. 空状态安全
 *
 * @compliance AGENTS.md §一 分层规则
  * @doc [V9-DOC-BACK-012, V9-DOC-ARCH-007, V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-BACK-015]
*/

import { useRotationSignalStore } from '@/store/rotationSignalStore'
import type { RotationSignal } from '@/services/scoring/rotationSignalDetector'
import { memoizeByRef, safeDivide, safeLength } from '@/lib/derivedCache'

// ============================================================
// 类型定义
// ============================================================

/** 强度分布统计 */
export interface StrengthDistribution {
  strong: number
  medium: number
  weak: number
  none: number  // 未触发
}

/** 板块统计聚合 */
export interface SectorStat {
  sectorId: string
  signalCount: number
  hasTriggered: boolean
  latestDetectedAt: number
  strengthLevel: 'strong' | 'medium' | 'weak' | 'none'
}

/** 信号条件详情（用于 tooltip） */
export interface SignalConditionsDetail {
  volumeBreakthrough: boolean
  capitalInflow: boolean
  goldenCross: boolean
  satisfiedCount: number  // 0-3
}

// ============================================================
// 派生查询：基础聚合
// ============================================================

/**
 * 信号列表是否为空
 */
export function isSignalsEmpty(): boolean {
  return useRotationSignalStore.getState().signals.length === 0
}

/**
 * 信号总数
 */
export function signalsCount(): number {
  return safeLength(useRotationSignalStore.getState().signals)
}

/**
 * 综合加载状态
 */
export function isLoading(): boolean {
  return useRotationSignalStore.getState().loading
}

/**
 * 综合错误
 */
export function hasError(): boolean {
  return useRotationSignalStore.getState().error !== null
}

// ============================================================
// 派生查询：信号筛选（memoizeByRef 缓存）
// ============================================================

/**
 * 已触发信号列表
 * 性能优化：基于 signals 引用记忆化
 */
export const triggeredSignalsMemo = memoizeByRef((signals: readonly RotationSignal[]): RotationSignal[] => {
  return signals.filter(s => s.triggered)
}, 'triggeredSignals')

/**
 * 获取已触发信号（自动传入最新 signals）
 */
export function triggeredSignals(): RotationSignal[] {
  return triggeredSignalsMemo(useRotationSignalStore.getState().signals)
}

/**
 * 按强度筛选信号
 */
export function signalsByStrength(strength: 'weak' | 'medium' | 'strong'): RotationSignal[] {
  return useRotationSignalStore.getState().signals.filter(
    s => s.triggered && s.strength === strength
  )
}

/**
 * 强信号快捷访问
 */
export function strongSignals(): RotationSignal[] {
  return signalsByStrength('strong')
}

/**
 * 中等信号
 */
export function mediumSignals(): RotationSignal[] {
  return signalsByStrength('medium')
}

/**
 * 弱信号
 */
export function weakSignals(): RotationSignal[] {
  return signalsByStrength('weak')
}

/**
 * 按板块查询信号
 */
export function bySector(sectorId: string): RotationSignal | undefined {
  return useRotationSignalStore.getState().signals.find(s => s.sectorId === sectorId)
}

// ============================================================
// 派生查询：统计聚合（memoizeByRef 缓存）
// ============================================================

function classifyStrength(signal: RotationSignal): keyof StrengthDistribution {
  if (!signal.triggered) return 'none'
  if (signal.strength === 'strong' || signal.strength === 'medium' || signal.strength === 'weak') {
    return signal.strength
  }
  return 'none'
}

/**
 * 强度分布统计
 * 性能优化：基于 signals 引用记忆化，单次遍历完成所有计数
 */
export const strengthDistribution = memoizeByRef((signals: readonly RotationSignal[]): StrengthDistribution => {
  const dist: StrengthDistribution = {
    strong: 0,
    medium: 0,
    weak: 0,
    none: 0,
  }
  for (const s of signals) {
    dist[classifyStrength(s)]++
  }
  return dist
}, 'strengthDistribution')

/**
 * 获取强度分布（自动传入最新 signals）
 */
export function getStrengthDistribution(): StrengthDistribution {
  return strengthDistribution(useRotationSignalStore.getState().signals)
}

/**
 * 已触发信号数量
 */
export function triggeredCount(): number {
  return triggeredSignals().length
}

/**
 * 信号触发率（0-1）
 */
export function triggeredRate(): number {
  const total = signalsCount()
  return safeDivide(triggeredCount(), total)
}

/**
 * 是否有信号触发
 */
export function hasAnyTriggered(): boolean {
  return triggeredCount() > 0
}

// ============================================================
// 派生查询：时间排序
// ============================================================

/**
 * 最新触发的信号（按 detectedAt 降序）
 * 注意：sort 会修改原数组，使用 [...].sort() 避免副作用
 */
export function latestSignals(limit: number = 10): RotationSignal[] {
  const triggered = triggeredSignals()
  return [...triggered]
    .sort((a, b) => b.detectedAt - a.detectedAt)
    .slice(0, limit)
}

/**
 * 最近 N 小时内触发的信号
 */
export function recentTriggered(hours: number = 24): RotationSignal[] {
  const now = Date.now()
  const threshold = now - hours * 60 * 60 * 1000
  return triggeredSignals().filter(s => s.detectedAt >= threshold)
}

// ============================================================
// 派生查询：板块聚合
// 注意：直接遍历 signals 基础状态，避免调用其他派生（性能优化）
// ============================================================

/**
 * 板块统计聚合
 * 性能优化：单次遍历 signals 完成所有计算，避免调用 signalsByStrength
 */
function updateStrengthLevel(stat: SectorStat, strength: Exclude<RotationSignal['strength'], 'none'>): void {
  const STRENGTH_PRIORITY: Record<SectorStat['strengthLevel'], number> = {
    none: 0,
    weak: 1,
    medium: 2,
    strong: 3,
  }
  if (STRENGTH_PRIORITY[strength] > STRENGTH_PRIORITY[stat.strengthLevel]) {
    stat.strengthLevel = strength
  }
}

/**
 * 板块统计聚合（memoized）。
 *
 * @param signals - 轮动信号列表
 * @returns 板块统计数组
 */
export const sectorStatsMemo = memoizeByRef((signals: readonly RotationSignal[]): SectorStat[] => {
  const statsMap = new Map<string, SectorStat>()

  for (const sig of signals) {
    let stat = statsMap.get(sig.sectorId)
    if (!stat) {
      stat = {
        sectorId: sig.sectorId,
        signalCount: 0,
        hasTriggered: false,
        latestDetectedAt: 0,
        strengthLevel: 'none',
      }
      statsMap.set(sig.sectorId, stat)
    }

    stat.signalCount++
    if (sig.triggered && sig.detectedAt > stat.latestDetectedAt) {
      stat.hasTriggered = true
      stat.latestDetectedAt = sig.detectedAt
      updateStrengthLevel(stat, sig.strength)
    }
  }

  return Array.from(statsMap.values())
}, 'sectorStats')

/**
 * 获取板块统计（自动传入最新 signals）
 */
export function getSectorStats(): SectorStat[] {
  return sectorStatsMemo(useRotationSignalStore.getState().signals)
}

/**
 * 是否为热门板块（触发 strong 信号）
 */
export function isHotSector(sectorId: string): boolean {
  const sig = bySector(sectorId)
  return sig?.triggered === true && sig.strength === 'strong'
}

/**
 * 板块热度排序（按强度+时间）
 */
export function hotSectors(limit: number = 10): string[] {
  const stats = getSectorStats()
  const strengthOrder = { strong: 3, medium: 2, weak: 1, none: 0 }
  return stats
    .filter(s => s.hasTriggered)
    .sort((a, b) => {
      const strengthDiff = strengthOrder[b.strengthLevel] - strengthOrder[a.strengthLevel]
      if (strengthDiff !== 0) return strengthDiff
      return b.latestDetectedAt - a.latestDetectedAt
    })
    .slice(0, limit)
    .map(s => s.sectorId)
}

/**
 * 信号条件详情（用于 tooltip）
 */
export function signalConditions(sectorId: string): SignalConditionsDetail | null {
  const sig = bySector(sectorId)
  if (!sig) return null
  const conditions = sig.conditions
  const satisfiedCount = [
    conditions.volumeBreakthrough,
    conditions.capitalInflow,
    conditions.goldenCross,
  ].filter(Boolean).length
  return {
    ...conditions,
    satisfiedCount,
  }
}

// ============================================================
// React Hook 形式派生（可选）
// ============================================================

/**
 * Hook：订阅强度分布
 */
export function useStrengthDistribution(): StrengthDistribution {
  const signals = useRotationSignalStore(state => state.signals)
  return strengthDistribution(signals)
}

/**
 * Hook：订阅板块统计
 */
export function useSectorStats(): SectorStat[] {
  const signals = useRotationSignalStore(state => state.signals)
  return sectorStatsMemo(signals)
}

/**
 * Hook：订阅已触发信号数量
 */
export function useTriggeredCount(): number {
  const signals = useRotationSignalStore(state => state.signals)
  return signals.filter(s => s.triggered).length
}

