import { describe, test, expect, beforeEach } from 'vitest'
import { useRotationSignalStore, triggeredSignals, bySector } from './rotationSignalStore'

/** 测试用输入数据（独立于 Mock 数据） */
const TEST_INPUTS = [
  {
    sectorId: '银行',
