    capitalFlow: { dailyNetFlow: [5, 3, -2, 8, 2] },
    goldenCross: { closes: [...Array(25).fill(100)] },
  },
]

/** 辅助函数：加载测试数据 */
function loadTestSignals() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  useRotationSignalStore.getState().fetchSignals(TEST_INPUTS as any)
}

describe('rotationSignalStore', () => {
  beforeEach(() => {
    useRotationSignalStore.getState().clearSignals()
  })

  // ============================================================
  // 初始状态
  // ============================================================

  test('初始状态为空', () => {
    const state = useRotationSignalStore.getState()
    expect(state.signals).toHaveLength(0)
    expect(state.loading).toBe(false)
    expect(state.error).toBeNull()
    expect(state.lastUpdated).toBe(0)
  })

  // ============================================================
  // fetchSignals
  // ============================================================

  test('fetchSignals 无输入返回空结果（不 fallback 到 Mock）', () => {
    useRotationSignalStore.getState().fetchSignals()
    const state = useRotationSignalStore.getState()
    expect(state.signals).toHaveLength(0)
    expect(state.loading).toBe(false)
  })

  test('fetchSignals 中银行板块应触发强信号', () => {
    loadTestSignals()
    const bankSignal = useRotationSignalStore.getState().signals.find((s) => s.sectorId === '银行')
    expect(bankSignal).toBeDefined()
    expect(bankSignal!.triggered).toBe(true)
    expect(bankSignal!.strength).toBe('strong')
  })

  test('fetchSignals 中钢铁板块应未触发', () => {
    loadTestSignals()
    const steelSignal = useRotationSignalStore.getState().signals.find((s) => s.sectorId === '钢铁')
    expect(steelSignal).toBeDefined()
    expect(steelSignal!.triggered).toBe(false)
  })

  test('fetchSignals 中每个信号包含完整条件', () => {
    loadTestSignals()
    const { signals } = useRotationSignalStore.getState()
    expect(signals.length).toBeGreaterThan(0)
    for (const signal of signals) {
      expect(signal.sectorId).toBeTruthy()
      expect(typeof signal.triggered).toBe('boolean')
      expect(typeof signal.conditions.volumeBreakthrough).toBe('boolean')
      expect(typeof signal.conditions.capitalInflow).toBe('boolean')
      expect(typeof signal.conditions.goldenCross).toBe('boolean')
      expect(signal.strength).toMatch(/^(weak|medium|strong)$/)
      expect(signal.detectedAt).toBeGreaterThan(0)
    }
  })

  test('fetchSignals 支持自定义输入', () => {
    useRotationSignalStore.getState().fetchSignals([
      {
        sectorId: 'TEST_SECTOR',
        volume: { history: [...Array(50).fill(1000), 5000, 5000, 5000, 5000, 5000] },
        capitalFlow: { dailyNetFlow: [10, 20, 30] },
        goldenCross: { closes: [...Array(25).fill(100), 105, 110, 110, 110, 110] },
      },
    ])
    const { signals } = useRotationSignalStore.getState()
    expect(signals).toHaveLength(1)
    expect(signals[0]!.sectorId).toBe('TEST_SECTOR')
  })

  // ============================================================
  // detectSignal
  // ============================================================

  test('detectSignal 更新指定板块', () => {
    loadTestSignals()
    const before = useRotationSignalStore.getState().signals.find((s) => s.sectorId === '银行')
    expect(before).toBeDefined()

    useRotationSignalStore.getState().detectSignal('银行', TEST_INPUTS as any)
    const after = useRotationSignalStore.getState().signals.find((s) => s.sectorId === '银行')
    expect(after!.triggered).toBe(before!.triggered)
  })

  test('detectSignal 不存在的板块无影响', () => {
    loadTestSignals()
    const beforeCount = useRotationSignalStore.getState().signals.length
    useRotationSignalStore.getState().detectSignal('不存在的板块', TEST_INPUTS as any)
    const afterCount = useRotationSignalStore.getState().signals.length
    expect(afterCount).toBe(beforeCount)
  })

  // ============================================================
  // clearSignals
  // ============================================================

  test('clearSignals 清空所有数据', () => {
    loadTestSignals()
    expect(useRotationSignalStore.getState().signals.length).toBeGreaterThan(0)
    useRotationSignalStore.getState().clearSignals()
    const state = useRotationSignalStore.getState()
    expect(state.signals).toHaveLength(0)
    expect(state.loading).toBe(false)
    expect(state.error).toBeNull()
    expect(state.lastUpdated).toBe(0)
  })

  // ============================================================
  // Getters
  // ============================================================

  test('triggeredSignals 只返回已触发的信号', () => {
    loadTestSignals()
    const triggered = triggeredSignals()
    for (const signal of triggered) {
      expect(signal.triggered).toBe(true)
    }
  })

  test('bySector 按板块ID查找', () => {
    loadTestSignals()
    const found = bySector('银行')
    expect(found).toBeDefined()
    expect(found!.sectorId).toBe('银行')

    const notFound = bySector('不存在的')
    expect(notFound).toBeUndefined()
  })
})

describe('rotationSignalStore clearSignals', () => {
  test('clearSignals 清空 signals 并恢复初始状态', () => {
    // 先填充数据
    loadTestSignals()
    const now = Date.now()
    useRotationSignalStore.setState({ loading: true, error: 'test error', lastUpdated: now })

    // 验证状态已填充
    const before = useRotationSignalStore.getState()
    expect(before.signals.length).toBeGreaterThan(0)
    expect(before.loading).toBe(true)
    expect(before.error).toBe('test error')
    expect(before.lastUpdated).toBe(now)

    // 执行 clearSignals
    useRotationSignalStore.getState().clearSignals()

    const after = useRotationSignalStore.getState()
    expect(after.signals).toHaveLength(0)
    expect(after.loading).toBe(false)
    expect(after.error).toBeNull()
    expect(after.lastUpdated).toBe(0)
  })
})

/**
 * @module useRuntimeTradingConfigStore
 * @description 运行时交易配置覆盖（阶段 A-1）
 *
 * ## 职责
 * - 提供 React 端订阅「交易配置覆盖」的入口
 * - 提供 applyOverride / reset / loadFromConfigApp 三组 action
 * - 底层调用 `setTradingConfigOverride()`（来自 `@/config/tradingConfig`），
 *   7 个高频消费文件（positionSizer / portfolioBuilder / riskEngine / signalGenerator
 *   / tradingService / createExecutionPlan / thresholds）通过 `getEffectiveTradingConfig()`
 *   自动感知变更
 *
 * ## 数据流
 * - 启动时：调用 `hydrateFromConfigApp()` 从 `localStorage['v9-app-config']` 读取
 *   ConfigApp 写入的旧值并应用为覆盖（兼容迁移）
 * - UI 提交（ConfigApp）：调 `applyOverride()` → setTradingConfigOverride → 下游生效
 * - 跨刷新：覆盖存在 process 内存 + localStorage 双轨；下次启动 hydrate 还原
 *
 * ## 配套
 * - `src/config/tradingConfig.ts` → `setTradingConfigOverride` / `getEffectiveTradingConfig` / `resetTradingConfigOverride`
 * - `src/apps/command/ConfigApp.tsx` → 提交时调 `useRuntimeTradingConfigStore.getState().applyOverride(...)`
  * @doc [V9-DOC-BACK-008, V9-DOC-BACK-013, V9-DOC-ARCH-008, V9-DOC-BACK-005, V9-DOC-DATA-032]
*/
import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import {
  setTradingConfigOverride,
  resetTradingConfigOverride,
  getDefaultTradingConfig,
  getEffectiveTradingConfig,
  type TradingConfigOverride,
  type TradingConfig,
} from '@/config/tradingConfig'

const logger = getLogger()

/** ConfigApp 写 localStorage 的 key（与 ConfigApp.tsx 保持一致） */
const APP_CONFIG_STORAGE_KEY = 'v9-app-config'

/** ConfigApp 写入的字段（仅取可覆盖部分） */
interface ConfigAppStored {
  portfolioValue?: number
  maxSinglePositionPct?: number
  maxDailyLossPct?: number
  stopLossPct?: number
  enablePaperTrading?: boolean
  // 其他字段（refreshInterval/autoRefresh/theme/language）不在 tradingConfig 覆盖范围
}

function loadFromConfigAppStorage(): ConfigAppStored | null {
  try {
    const raw = localStorage.getItem(APP_CONFIG_STORAGE_KEY)
    if (!raw) return null
    return JSON.parse(raw) as ConfigAppStored
  } catch (err) { console.warn('[runtimeTradingConfigStore.ts]', err);
    return null
  }
}

/** 把 ConfigApp 字段映射为 tradingConfig 覆盖 */
function mapConfigAppToOverride(stored: ConfigAppStored): TradingConfigOverride {
  return {
    risk: {
      ...(typeof stored.portfolioValue === 'number' && stored.portfolioValue > 0
        ? { portfolioValue: stored.portfolioValue }
        : {}),
      ...(typeof stored.maxSinglePositionPct === 'number'
        ? { maxSinglePositionPct: stored.maxSinglePositionPct }
        : {}),
    },
    signalThresholds: {
      ...(typeof stored.stopLossPct === 'number'
        ? { fixedStopLossPct: stored.stopLossPct, trailingStopDrawdownPct: stored.stopLossPct }
        : {}),
    },
    // maxDailyLossPct 暂无对应 tradingConfig 字段（已映射到 risk.maxTradesPerDay 之外，保留未来扩展）
  }
}

interface RuntimeTradingConfigState {
  /** 当前生效配置（含默认 ∪ 覆盖） */
  effective: TradingConfig
  /** 标记已 hydrate（避免重复读取 localStorage） */
  hydrated: boolean

  /** 从 ConfigApp 写入的 localStorage 还原覆盖（应用启动时调用一次） */
  hydrateFromConfigApp: () => void
  /** 应用新的覆盖（部分字段） */
  applyOverride: (override: TradingConfigOverride) => void
  /** 重置为默认 */
  resetToDefault: () => void
  /** 刷新 effective（用于订阅 setTradingConfigOverride 后的手动重读） */
  refresh: () => void
}

/**
 * useRuntimeTradingConfigStore
 */
export const useRuntimeTradingConfigStore = create<RuntimeTradingConfigState>((set) => ({
  effective: getEffectiveTradingConfig(),
  hydrated: false,

  hydrateFromConfigApp: () => {
    const stored = loadFromConfigAppStorage()
    if (!stored) {
      set({ hydrated: true })
      return
    }
    const override = mapConfigAppToOverride(stored)
    if (Object.keys(override.signalThresholds ?? {}).length > 0 || Object.keys(override.kelly ?? {}).length > 0 || Object.keys(override.risk ?? {}).length > 0) {
      setTradingConfigOverride(override)
      logger.info('[useRuntimeTradingConfigStore] hydrate 从 ConfigApp localStorage 还原覆盖', {
        keys: Object.keys(override),
      })
    } else {
      logger.info('[useRuntimeTradingConfigStore] hydrate 未发现可还原字段')
    }
    set({ effective: getEffectiveTradingConfig(), hydrated: true })
  },

  applyOverride: (override) => {
    setTradingConfigOverride(override)
    const next = getEffectiveTradingConfig()
    logger.info('[useRuntimeTradingConfigStore] applyOverride 完成', {
      riskDelta: { portfolioValue: next.risk.portfolioValue },
    })
    set({ effective: next })
  },

  resetToDefault: () => {
    resetTradingConfigOverride()
    const next = getDefaultTradingConfig()
    logger.info('[useRuntimeTradingConfigStore] resetToDefault 完成')
    set({ effective: next })
  },

  refresh: () => {
    set({ effective: getEffectiveTradingConfig() })
  },
}))

/** 调试用：导出默认配置 + 覆盖键名，方便 IDE 跳转 */
export const RUNTIME_TRADING_CONFIG_DEFAULTS = getDefaultTradingConfig()

/**
 * @module scoreDocStore
 * @lifecycle @Global
 * @description 评分文档版本库页面状态管理。管理股票代码选择、股票列表、
 * 评分文档版本列表，提供加载、刷新、清空、导出等操作。
 *
 * @see @/pages/analysis/ScoreDocPage.tsx - 消费此 Store 的评分文档页面
 *
 * @compliance
 * - 所有数据请求经 Store Action 分发
 * - 核心分支包含 logger.info 打印
 * - 遵循现有 Zustand Store 风格
  * @doc [V9-DOC-BACK-010, V9-DOC-BACK-012, V9-DOC-PROJ-002, V9-DOC-PROJ-003, V9-DOC-ARCH-008]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import type { ScoreDocVersion, Stock } from '@/data/types'
import type { ScoreComparisonMode, ScoreComparisonResult, ScoreComparisonTimelineItem } from '@/types/modules/score.types'
import {
  buildReportMarkdown,
  getRecentVersions,
  exportSymbolMd,
  listScoreDocsBySymbol,
  buildScoreDocDiff,
  type ScoreDocDiff,
  compareTwoVersions,
  compareTwoStocksLatest,
  getScoreTimeline,
} from '@/services/analysis/scoreDocService'
import { listPoolItems } from '@/services/pool/poolService'
import type { PoolItem } from '@/types/modules/pool.types'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, MODULE_ID, STORE_NAME } from '@/config/dbConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

function poolItemToStock(item: PoolItem): Stock {
  return {
    ...item,
    researchStatus: item.status,
  }
}

// ============================================================
// 类型定义
// ============================================================

export interface ScoreDocState {
  /** 当前选中的股票代码 */
  symbol: string
  /** 股票列表（用于下拉选择） */
  stocks: Stock[]
  /** 评分文档版本列表 */
  versions: ScoreDocVersion[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 历史文档列表（供 ScoreHistoryPanel 使用） */
  historyDocs: ScoreDocVersion[]
  /** 历史文档差异（最新版本 vs 上一版本） */
  historyDiff: ScoreDocDiff | null
  /** 历史文档加载状态 */
  historyLoading: boolean
  /** 历史文档错误信息 */
  historyError: string | null
  /** 比对模式 */
  comparisonMode: ScoreComparisonMode
  /** 比对左侧版本号（同股票模式）或股票代码（跨股票模式） */
  comparisonLeft: string
  /** 比对右侧版本号（同股票模式）或股票代码（跨股票模式） */
  comparisonRight: string
  /** 比对结果 */
  comparisonResult: ScoreComparisonResult | null
  /** 比对加载状态 */
  comparisonLoading: boolean
  /** 比对错误信息 */
  comparisonError: string | null
  /** 评分时间轴数据 */
  timelineData: ScoreComparisonTimelineItem[]
  /** 时间轴加载状态 */
  timelineLoading: boolean

  // Actions
  /** 设置当前股票代码 */
  setSymbol: (symbol: string) => void
  /** 加载股票列表 */
  loadStocks: () => Promise<void>
  /** 加载当前股票的评分文档版本 */
  loadVersions: () => Promise<void>
  /** 刷新当前股票的评分文档版本 */
  refresh: () => Promise<void>
  /** 重置当前选择及结果（保留股票列表） */
  reset: () => void
  /** 导出当前股票全部 Markdown */
  exportAll: () => Promise<void>
  /** 加载股票代码列表（供下拉选择，封装 DataBridge.query(queryList)）） */
  loadStockSymbols: () => Promise<string[]>
  /** 生成研究报告 Markdown（封装 buildReportMarkdown + getRecentVersions） */
  generateReport: (symbol: string) => Promise<{ symbol: string; version: number; markdown: string; generatedAt: string }>
  /** 加载历史文档列表并计算差异（供 ScoreHistoryPanel 使用） */
  loadHistoryDocs: (symbol: string) => Promise<void>
  /** 设置比对模式 */
  setComparisonMode: (mode: ScoreComparisonMode) => void
  /** 设置比对左侧值 */
  setComparisonLeft: (value: string) => void
  /** 设置比对右侧值 */
  setComparisonRight: (value: string) => void
  /** 执行版本比对（同股票模式） */
  runVersionComparison: (symbol: string, leftVersion: number, rightVersion: number) => Promise<void>
  /** 执行股票比对（跨股票模式） */
  runStockComparison: (leftSymbol: string, rightSymbol: string) => Promise<void>
  /** 加载评分时间轴 */
  loadTimeline: (symbol: string) => Promise<void>
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  symbol: '',
  stocks: [] as Stock[],
  versions: [] as ScoreDocVersion[],
  loading: false,
  error: null as string | null,
  historyDocs: [] as ScoreDocVersion[],
  historyDiff: null as ScoreDocDiff | null,
  historyLoading: false,
  historyError: null as string | null,
  comparisonMode: 'same-stock-versions' as ScoreComparisonMode,
  comparisonLeft: '',
  comparisonRight: '',
  comparisonResult: null as ScoreComparisonResult | null,
  comparisonLoading: false,
  comparisonError: null as string | null,
  timelineData: [] as ScoreComparisonTimelineItem[],
  timelineLoading: false,
}

// ============================================================
// Store
// ============================================================

/**
 * useScoreDocStore
 */
export const useScoreDocStore = create<ScoreDocState>((set, get) => ({
  ...initialState,

  setSymbol: (symbol: string) => {
    logger.info(`[scoreDocStore] setSymbol: ${symbol}`)
    set({ symbol })
  },

  loadStocks: async () => {
    logger.info('[scoreDocStore] loadStocks 开始')
    set({ loading: true, error: null })

    try {
      const result = await listPoolItems()
      if (result.success && result.data) {
        const stocks = result.data.map((item) => poolItemToStock(item))
        set({ stocks, loading: false })
        logger.info(`[scoreDocStore] loadStocks 完成: ${stocks.length} 只股票`)
      } else {
        const message = result.error ?? '加载股票列表失败'
        logger.error(`[scoreDocStore] loadStocks 失败: ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadStocks 异常: ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  loadVersions: async () => {
    const { symbol } = get()
    if (!symbol) {
      logger.info('[scoreDocStore] loadVersions 跳过: symbol 为空')
      set({ versions: [], error: null })
      return
    }

    logger.info(`[scoreDocStore] loadVersions 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await getRecentVersions(symbol)
      if (result.success && result.data) {
        set({ versions: result.data, loading: false })
        logger.info(`[scoreDocStore] loadVersions 完成: ${symbol}, ${result.data.length} 个版本`)
      } else {
        const message = result.error ?? '加载评分文档版本失败'
        logger.error(`[scoreDocStore] loadVersions 失败: ${symbol}, ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadVersions 异常: ${symbol}, ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  refresh: async () => {
    const { symbol } = get()
    if (!symbol) {
      logger.info('[scoreDocStore] refresh 跳过: symbol 为空')
      return
    }

    logger.info(`[scoreDocStore] refresh 开始: ${symbol}`)
    set({ loading: true, error: null })

    try {
      const result = await getRecentVersions(symbol)
      if (result.success && result.data) {
        set({ versions: result.data, loading: false })
        logger.info(`[scoreDocStore] refresh 完成: ${symbol}, ${result.data.length} 个版本`)
      } else {
        const message = result.error ?? '加载评分文档版本失败'
        logger.error(`[scoreDocStore] refresh 失败: ${symbol}, ${message}`)
        set({ error: message, loading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] refresh 异常: ${symbol}, ${message}`)
      set({ error: `加载失败：${message}`, loading: false })
    }
  },

  reset: () => {
    logger.info('[scoreDocStore] reset')
    set({ symbol: '', versions: [], error: null, loading: false })
    withBroadcast(EVENT_NAMES.SCORE_DOCS_CHANGED, { action: 'reset' })
  },

  exportAll: async () => {
    const { symbol, versions } = get()
    if (!symbol || versions.length === 0) {
      logger.warn('[scoreDocStore] exportAll 跳过: symbol 为空或版本列表为空')
      return
    }

    logger.info(`[scoreDocStore] exportAll 开始: ${symbol}`)

    try {
      const result = await exportSymbolMd(symbol)
      if (result.success && result.data) {
        const blob = new Blob([result.data], { type: 'text/markdown;charset=utf-8' })
        const url = URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = `${symbol}_score_docs.md`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        URL.revokeObjectURL(url)
        logger.info(`[scoreDocStore] exportAll 完成: ${symbol}`)
      } else {
        const message = result.error ?? '导出失败'
        logger.error(`[scoreDocStore] exportAll 失败: ${symbol}, ${message}`)
        set({ error: message })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] exportAll 异常: ${symbol}, ${message}`)
      set({ error: `导出失败：${message}` })
    }
  },

  loadHistoryDocs: async (symbol) => {
    if (!symbol) {
      logger.info('[scoreDocStore] loadHistoryDocs 跳过: symbol 为空')
      set({ historyDocs: [], historyDiff: null, historyError: null, historyLoading: false })
      return
    }

    logger.info(`[scoreDocStore] loadHistoryDocs 开始: ${symbol}`)
    set({ historyLoading: true, historyError: null })

    try {
      const result = await listScoreDocsBySymbol(symbol)
      if (result.success) {
        const list = result.data ?? []
        let diff: ScoreDocDiff | null = null
        if (list.length >= 2) {
          const latest = list[0]!
          const previous = list[1]!
          diff = buildScoreDocDiff(latest, previous)
        }
        set({ historyDocs: list, historyDiff: diff, historyLoading: false })
        logger.info(`[scoreDocStore] loadHistoryDocs 完成: ${symbol}, ${list.length} 个版本`)
      } else {
        const message = result.error ?? '加载失败'
        logger.error(`[scoreDocStore] loadHistoryDocs 失败: ${symbol}, ${message}`)
        set({ historyError: message, historyLoading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadHistoryDocs 异常: ${symbol}, ${message}`)
      set({ historyError: `加载失败：${message}`, historyLoading: false })
    }
  },

  loadStockSymbols: async () => {
    logger.info('[scoreDocStore] loadStockSymbols 开始')
    try {
      const result = await dataBridge.query<Stock[]>({
        action: ENVELOPE_ACTION.queryList,
        store: STORE_NAME.stocks,
        source: MODULE_ID.analyzer,
      })

      if (!result.success) {
        const errorMessage = result.error ?? '查询股票列表失败'
        logger.error(`[scoreDocStore] loadStockSymbols 查询失败: ${errorMessage}`)
        throw new Error(errorMessage)
      }

      const stocks = result.data ?? []
      const uniqueSymbols = Array.from(new Set(stocks.map(s => s.symbol))).sort()
      logger.info(`[scoreDocStore] loadStockSymbols 完成: ${uniqueSymbols.length} 个代码`)
      return uniqueSymbols
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadStockSymbols 异常: ${message}`)
      throw err
    }
  },

  generateReport: async (symbol) => {
    logger.info(`[scoreDocStore] generateReport 开始: ${symbol}`)
    try {
      const recentVersionsResult = await getRecentVersions(symbol, 1)
      if (!recentVersionsResult.success || !recentVersionsResult.data || recentVersionsResult.data.length === 0) {
        throw new Error(`股票 ${symbol} 暂无评分文档，请先生成评分`)
      }
      const latestVersion = recentVersionsResult.data[0]!
      const markdown = buildReportMarkdown(latestVersion)
      const report = {
        symbol,
        version: latestVersion.version,
        markdown,
        generatedAt: new Date().toISOString(),
      }
      logger.info(`[scoreDocStore] generateReport 完成: ${symbol} V${latestVersion.version}`)
      return report
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] generateReport 异常: ${symbol}, ${message}`)
      throw err
    }
  },

  setComparisonMode: (mode: ScoreComparisonMode) => {
    logger.info(`[scoreDocStore] setComparisonMode: ${mode}`)
    set({ comparisonMode: mode, comparisonLeft: '', comparisonRight: '', comparisonResult: null, comparisonError: null })
  },

  setComparisonLeft: (value: string) => {
    set({ comparisonLeft: value })
  },

  setComparisonRight: (value: string) => {
    set({ comparisonRight: value })
  },

  runVersionComparison: async (symbol: string, leftVersion: number, rightVersion: number) => {
    logger.info(`[scoreDocStore] runVersionComparison 开始: ${symbol} V${leftVersion} vs V${rightVersion}`)
    set({ comparisonLoading: true, comparisonError: null })

    try {
      const result = await compareTwoVersions(symbol, leftVersion, rightVersion)
      if (result.success && result.data) {
        set({ comparisonResult: result.data, comparisonLoading: false })
        logger.info(`[scoreDocStore] runVersionComparison 完成: ${symbol} V${leftVersion} vs V${rightVersion}`)
      } else {
        const message = result.error ?? '版本比对失败'
        logger.error(`[scoreDocStore] runVersionComparison 失败: ${message}`)
        set({ comparisonError: message, comparisonLoading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] runVersionComparison 异常: ${message}`)
      set({ comparisonError: `比对失败：${message}`, comparisonLoading: false })
    }
  },

  runStockComparison: async (leftSymbol: string, rightSymbol: string) => {
    logger.info(`[scoreDocStore] runStockComparison 开始: ${leftSymbol} vs ${rightSymbol}`)
    set({ comparisonLoading: true, comparisonError: null })

    try {
      const result = await compareTwoStocksLatest(leftSymbol, rightSymbol)
      if (result.success && result.data) {
        set({ comparisonResult: result.data, comparisonLoading: false })
        logger.info(`[scoreDocStore] runStockComparison 完成: ${leftSymbol} vs ${rightSymbol}`)
      } else {
        const message = result.error ?? '股票比对失败'
        logger.error(`[scoreDocStore] runStockComparison 失败: ${message}`)
        set({ comparisonError: message, comparisonLoading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] runStockComparison 异常: ${message}`)
      set({ comparisonError: `比对失败：${message}`, comparisonLoading: false })
    }
  },

  loadTimeline: async (symbol: string) => {
    if (!symbol) {
      logger.info('[scoreDocStore] loadTimeline 跳过: symbol 为空')
      set({ timelineData: [], timelineLoading: false })
      return
    }

    logger.info(`[scoreDocStore] loadTimeline 开始: ${symbol}`)
    set({ timelineLoading: true })

    try {
      const result = await getScoreTimeline(symbol)
      if (result.success && result.data) {
        set({ timelineData: result.data, timelineLoading: false })
        logger.info(`[scoreDocStore] loadTimeline 完成: ${symbol}, ${result.data.length} 个版本`)
      } else {
        const message = result.error ?? '加载时间轴失败'
        logger.error(`[scoreDocStore] loadTimeline 失败: ${message}`)
        set({ timelineData: [], timelineLoading: false })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[scoreDocStore] loadTimeline 异常: ${message}`)
      set({ timelineData: [], timelineLoading: false })
    }
  },
}))

// ============================================================
// DataBridge 订阅（用于跨模块数据同步）
// ============================================================

let _unsubscribeScoreDocs: (() => void) | undefined

/**
 * initScoreDocStoreSubscriptions
 */
export function initScoreDocStoreSubscriptions(): () => void {
  destroyScoreDocStoreSubscriptions()
  logger.info('[scoreDocStore] 初始化 DataBridge score_docs 频道订阅')

  _unsubscribeScoreDocs = dataBridge.subscribe(
    'score_docs',
    (envelope) => {
      if (envelope.meta.action === ENVELOPE_ACTION.saveScoreDocs) {
        logger.info('[scoreDocStore] DataBridge event received: saveScoreDocs', {
          traceId: envelope.meta.traceId,
        })
      }
    },
  )

  return () => destroyScoreDocStoreSubscriptions()
}

/**
 * destroyScoreDocStoreSubscriptions
 * @returns void
 */
export function destroyScoreDocStoreSubscriptions(): void {
  if (_unsubscribeScoreDocs) {
    _unsubscribeScoreDocs()
    _unsubscribeScoreDocs = undefined
  }
}

/**
 * @fileoverview 检索状态 Store
 *
 * 管理检索条件、结果、分面统计与视图模式。
 *
 * @module store/searchStore
 * @created 2026-07-14 - 双通道整改 P2-3
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-076, V9-DOC-DATA-075, V9-DOC-DATA-073]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import type { SearchCriteria, SearchResult } from '@/types/modules/data-sync.types'

const logger = getLogger()

/** 视图模式 */
export type SearchViewMode = 'timeline' | 'grouped'

/** 检索 Store 状态 */
export interface SearchState {
  // 检索条件
  keyword: string
  datePreset: 'today' | 'yesterday' | 'last7days' | 'last30days' | 'all' | 'custom'
  channels: Array<'auto-collect' | 'file-import' | 'manual-trigger'>
  symbols: string[]
  dimensions: string[]
  statuses: Array<'success' | 'partial' | 'failed'>
  fileTypes: string[]

  // 分页
  page: number
  pageSize: number

  // 视图
  viewMode: SearchViewMode

  // 结果
  result: SearchResult | null
  loading: boolean

  // 操作
  setKeyword: (keyword: string) => void
  setDatePreset: (preset: SearchState['datePreset']) => void
  toggleChannel: (channel: 'auto-collect' | 'file-import' | 'manual-trigger') => void
  toggleStatus: (status: 'success' | 'partial' | 'failed') => void
  toggleFileType: (fileType: string) => void
  setSymbols: (symbols: string[]) => void
  setDimensions: (dimensions: string[]) => void
  setPage: (page: number) => void
  setViewMode: (mode: SearchViewMode) => void
  setResult: (result: SearchResult) => void
  setLoading: (loading: boolean) => void
  buildCriteria: () => SearchCriteria
  reset: () => void
}

const initialState = {
  keyword: '',
  datePreset: 'all' as SearchState['datePreset'],
  channels: [] as SearchState['channels'],
  symbols: [] as string[],
  dimensions: [] as string[],
  statuses: [] as SearchState['statuses'],
  fileTypes: [] as string[],
  page: 1,
  pageSize: 20,
  viewMode: 'timeline' as SearchViewMode,
  result: null,
  loading: false,
}

/** 计算时间范围预设 */
function computeDateRange(preset: SearchState['datePreset']): SearchCriteria['dateRange'] {
  if (preset === 'all') return undefined
  const now = new Date()
  const start = new Date()
  switch (preset) {
    case 'today':
      start.setHours(0, 0, 0, 0)
      return { start: start.toISOString(), end: now.toISOString(), preset: 'custom' }
    case 'yesterday': {
      start.setDate(start.getDate() - 1)
      start.setHours(0, 0, 0, 0)
      const end = new Date(start)
      end.setHours(23, 59, 59, 999)
      return { start: start.toISOString(), end: end.toISOString(), preset: 'custom' }
    }
    case 'last7days':
      start.setDate(start.getDate() - 7)
      return { start: start.toISOString(), end: now.toISOString(), preset: 'last7days' }
    case 'last30days':
      start.setDate(start.getDate() - 30)
      return { start: start.toISOString(), end: now.toISOString(), preset: 'last30days' }
    default:
      return undefined
  }
}

/**
 * useSearchStore
 */
export const useSearchStore = create<SearchState>((set, get) => ({
  ...initialState,

  setKeyword: (keyword) => {
    set({ keyword, page: 1 })
  },

  setDatePreset: (datePreset) => {
    set({ datePreset, page: 1 })
  },

  toggleChannel: (channel) => {
    set((state) => {
      const exists = state.channels.includes(channel)
      return {
        channels: exists
          ? state.channels.filter(c => c !== channel)
          : [...state.channels, channel],
        page: 1,
      }
    })
  },

  toggleStatus: (status) => {
    set((state) => {
      const exists = state.statuses.includes(status)
      return {
        statuses: exists
          ? state.statuses.filter(s => s !== status)
          : [...state.statuses, status],
        page: 1,
      }
    })
  },

  toggleFileType: (fileType) => {
    set((state) => {
      const exists = state.fileTypes.includes(fileType)
      return {
        fileTypes: exists
          ? state.fileTypes.filter(f => f !== fileType)
          : [...state.fileTypes, fileType],
        page: 1,
      }
    })
  },

  setSymbols: (symbols) => set({ symbols, page: 1 }),
  setDimensions: (dimensions) => set({ dimensions, page: 1 }),
  setPage: (page) => set({ page }),
  setViewMode: (viewMode) => set({ viewMode }),

  setResult: (result) => {
    set({ result })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'searchComplete', total: result.total })
    logger.info('[searchStore] 检索结果已设置', { total: result.total, page: result.page })
  },

  setLoading: (loading) => set({ loading }),

  buildCriteria: () => {
    const state = get()
    return {
      keyword: state.keyword || undefined,
      dateRange: computeDateRange(state.datePreset),
      channels: state.channels.length > 0 ? state.channels : undefined,
      symbols: state.symbols.length > 0 ? state.symbols : undefined,
      dimensions: state.dimensions.length > 0 ? state.dimensions : undefined,
      statuses: state.statuses.length > 0 ? state.statuses : undefined,
      fileTypes: state.fileTypes.length > 0 ? state.fileTypes : undefined,
      sortBy: 'timestamp',
      sortOrder: 'desc',
      page: state.page,
      pageSize: state.pageSize,
    }
  },

  reset: () => {
    set(initialState)
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'searchReset' })
    logger.info('[searchStore] 已重置')
  },
}))

/**
 * @module sevenDimConfigStore
 * @description 七维采集配置 Store（Zustand），支持全层级配置与持久化。
 *
 * 职责：
 * - 管理 8 个采集维度的高级配置（启用、频率、数据源、字段、策略、优先级）
 * - 管理当前策略模板与全局参数
 * - 提供配置序列化 / 反序列化能力
 * - 通过 DataBridge.forward() 持久化到 IndexedDB
  * @doc [V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-DATA-073, V9-DOC-DATA-068, V9-DOC-FRONT-020]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID, STORE_NAME } from '@/config/dbConfig'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import type {
  CollectionConfig,
  DimensionPipelineConfig,
  GlobalCollectPolicy,
  SourcePriorityItem,
  StrategyTemplateId,
  UpdateFrequency,
  DataSourceType,
  RetryPolicy,
  TimeoutPolicy,
  FallbackPolicy,
} from '@/types/modules/collection.types'
import {
  DEFAULT_DIMENSIONS,
  STRATEGY_TEMPLATES,
  GLOBAL_LIMITS,
  estimateTotalMonthlyCalls,
  DEFAULT_RETRY_POLICY,
  DEFAULT_TIMEOUT_POLICY,
} from '@/config/collectConfig'
import { upgradeDimensionsToPipeline, runBatchTrace } from '@/services/data-collector/collectionPipeline'
import { useCollectionRuntimeStore } from '@/store/collectionRuntimeStore'
import { useIntentionPoolStore } from '@/store/intentionPoolStore'

const logger = getLogger()

const COLLECT_CONFIG_ID = 'default'

// ============================================================
// Store 接口定义
// ============================================================

export interface SevenDimConfigState {
  // --- 状态 ---
  activeTemplate: StrategyTemplateId
  dimensions: DimensionPipelineConfig[]
  global: GlobalCollectPolicy
  symbolCount: number
  historyDays: number
  isDirty: boolean
  isSaving: boolean
  isCollecting: boolean
  /** 当前正在采集的维度 code 列表（空表示无采集进行中） */
  collectingDimensions: string[]
  collectProgress: number
  error: string | null

  // --- 派生计算 ---
  enabledCount: () => number
  monthlyCallEstimate: () => number
  isClickable: (dimensionCode?: string) => boolean
  tooltipText: (dimensionCode?: string) => string
  getCollectionConfig: () => CollectionConfig

  // --- Actions ---
  applyTemplate: (templateId: StrategyTemplateId) => void
  toggleDimension: (code: string) => void
  setDimensionFrequency: (code: string, frequency: UpdateFrequency) => void
  setDimensionSources: (code: string, sources: DataSourceType[]) => void
  setDimensionSourcePriority: (code: string, priority: SourcePriorityItem[]) => void
  setDimensionPolicy: (
    code: string,
    policy: Partial<{ retryPolicy: RetryPolicy; timeoutPolicy: TimeoutPolicy; fallbackPolicy: FallbackPolicy }>,
  ) => void
  setDimensionFields: (code: string, fields: string[]) => void
  setSymbolCount: (count: number) => void
  setHistoryDays: (days: number) => void
  setGlobalPolicy: (policy: Partial<GlobalCollectPolicy>) => void
  reset: () => void
  saveConfig: () => Promise<void>
  loadConfig: () => Promise<void>
  runCollection: () => Promise<void>
  clearError: () => void
}

// ============================================================
// 辅助函数
// ============================================================

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value))
}

function createDefaultGlobal(): GlobalCollectPolicy {
  return {
    maxSymbols: GLOBAL_LIMITS.maxSymbols,
    defaultBatchSize: GLOBAL_LIMITS.defaultBatchSize,
    rateLimitPerMinute: GLOBAL_LIMITS.rateLimitPerMinute,
    rateLimitPerHour: GLOBAL_LIMITS.rateLimitPerHour,
    rateLimitPerDay: GLOBAL_LIMITS.rateLimitPerDay,
    notifyOnComplete: true,
    notifyOnError: true,
    defaultTimeoutMs: DEFAULT_TIMEOUT_POLICY.requestTimeoutMs,
    defaultRetries: DEFAULT_RETRY_POLICY.maxRetries,
  }
}

function createPipelineDimensions(): DimensionPipelineConfig[] {
  return upgradeDimensionsToPipeline(DEFAULT_DIMENSIONS as DimensionPipelineConfig[])
}

function generateDimensionsFromTemplate(templateId: StrategyTemplateId): DimensionPipelineConfig[] {
  const template = STRATEGY_TEMPLATES.find((t) => t.id === templateId)
  if (!template) return createPipelineDimensions()

  return createPipelineDimensions().map((dim) => ({
    ...dim,
    enabled: template.dimensions.includes(dim.code),
    frequency: template.dimensions.includes(dim.code) ? template.updateInterval : dim.frequency,
    sources: template.sources,
  }))
}

function buildCollectionConfig(state: SevenDimConfigState): CollectionConfig {
  return {
    version: '1.0.0',
    activeTemplate: state.activeTemplate,
    dimensions: state.dimensions,
    global: state.global,
    symbolCount: state.symbolCount,
    historyDays: state.historyDays,
    updatedAt: Date.now(),
  }
}

/**
 * 从用户意向池读取采集标的列表。
 * 意向池为空时回退到空数组（调用方会 skip 采集）。
 */
function resolveDefaultSymbols(_count: number): string[] {
  const poolItems = useIntentionPoolStore.getState().items
  if (poolItems.length === 0) {
    logger.warn('[SevenDimConfigStore] 意向池为空，无可采集标的')
    return []
  }
  return poolItems
    .map((item) => item.symbol.trim().toUpperCase())
    .filter((symbol) => symbol.length > 0)
}

// ============================================================
// Store 实现
// ============================================================

const initialState: Omit<
  SevenDimConfigState,
  | 'enabledCount'
  | 'monthlyCallEstimate'
  | 'isClickable'
  | 'tooltipText'
  | 'getCollectionConfig'
  | 'applyTemplate'
  | 'toggleDimension'
  | 'setDimensionFrequency'
  | 'setDimensionSources'
  | 'setDimensionSourcePriority'
  | 'setDimensionPolicy'
  | 'setDimensionFields'
  | 'setSymbolCount'
  | 'setHistoryDays'
  | 'setGlobalPolicy'
  | 'reset'
  | 'saveConfig'
  | 'loadConfig'
  | 'runCollection'
  | 'clearError'
> = {
  activeTemplate: 'full',
  dimensions: generateDimensionsFromTemplate('full'),
  global: createDefaultGlobal(),
  symbolCount: 40,
  historyDays: 252,
  isDirty: false,
  isSaving: false,
  isCollecting: false,
  collectingDimensions: [],
  collectProgress: 0,
  error: null,
}

/**
 * useSevenDimConfigStore
 */
export const useSevenDimConfigStore = create<SevenDimConfigState>((set, get) => ({
  ...initialState,

  enabledCount: () => get().dimensions.filter((d) => d.enabled).length,

  monthlyCallEstimate: () =>
    estimateTotalMonthlyCalls(get().dimensions, get().symbolCount),

  isClickable: (dimensionCode) => {
    const state = get()
    if (state.isSaving) return false
    if (dimensionCode) return !state.collectingDimensions.includes(dimensionCode)
    return state.collectingDimensions.length === 0
  },

  tooltipText: (dimensionCode) => {
    const state = get()
    if (state.isSaving) return '配置保存中，请稍候...'
    if (dimensionCode) {
      return state.collectingDimensions.includes(dimensionCode)
        ? `维度 ${dimensionCode} 采集中，请稍候...`
        : ''
    }
    if (state.collectingDimensions.length > 0)
      return `维度 ${state.collectingDimensions.join(', ')} 采集中，请稍候...`
    return ''
  },

  getCollectionConfig: () => buildCollectionConfig(get()),

  applyTemplate: (templateId) => {
    const template = STRATEGY_TEMPLATES.find((t) => t.id === templateId)
    if (!template) {
      logger.warn(`[SevenDimConfigStore] 未找到策略模板: ${templateId}`)
      return
    }

    logger.info(`[SevenDimConfigStore] 应用策略模板: ${template.name}`, {
      dimensions: template.dimensions,
      frequency: template.updateInterval,
    })

    set({
      activeTemplate: templateId,
      dimensions: generateDimensionsFromTemplate(templateId),
      historyDays: template.historyDays,
      isDirty: true,
    })
  },

  toggleDimension: (code) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, enabled: !dim.enabled } : dim,
      ),
      isDirty: true,
    }))

    const dim = get().dimensions.find((d) => d.code === code)
    logger.info(`[SevenDimConfigStore] 维度切换: ${code} → ${dim?.enabled ? '启用' : '禁用'}`)
  },

  setDimensionFrequency: (code, frequency) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, frequency } : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度频率更新: ${code} → ${frequency}`)
  },

  setDimensionSources: (code, sources) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code
          ? {
              ...dim,
              sources,
              sourcePriority: sources.length > 0
                ? dim.sourcePriority.filter((item) => {
                    const mapped = item.id === 'akshare' ? 'akshare' : 'ifind'
                    return sources.includes(mapped) || item.id === 'mock'
                  })
                : dim.sourcePriority,
            }
          : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度数据源更新: ${code} → ${sources.join(', ')}`)
  },

  setDimensionSourcePriority: (code, sourcePriority) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, sourcePriority } : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度优先级更新: ${code} → ${sourcePriority.map((s) => s.id).join('>')}`)
  },

  setDimensionPolicy: (code, policy) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code
          ? {
              ...dim,
              retryPolicy: policy.retryPolicy ?? dim.retryPolicy,
              timeoutPolicy: policy.timeoutPolicy ?? dim.timeoutPolicy,
              fallbackPolicy: policy.fallbackPolicy ?? dim.fallbackPolicy,
            }
          : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度策略更新: ${code}`)
  },

  setDimensionFields: (code, fields) => {
    set((state) => ({
      dimensions: state.dimensions.map((dim) =>
        dim.code === code ? { ...dim, fields } : dim,
      ),
      isDirty: true,
    }))

    logger.info(`[SevenDimConfigStore] 维度字段更新: ${code} → ${fields.join(',')}`)
  },

  setSymbolCount: (count) => {
    const clamped = clamp(count, 1, GLOBAL_LIMITS.maxSymbols)
    set({ symbolCount: clamped, isDirty: true })
    logger.info(`[SevenDimConfigStore] 标的数设置: ${clamped}`)
  },

  setHistoryDays: (days) => {
    const clamped = clamp(days, 1, 1000)
    set({ historyDays: clamped, isDirty: true })
  },

  setGlobalPolicy: (policy) => {
    set((state) => ({
      global: { ...state.global, ...policy },
      isDirty: true,
    }))

    logger.info('[SevenDimConfigStore] 全局策略更新', policy)
  },

  reset: () => {
    logger.info('[SevenDimConfigStore] 重置为默认配置')
    set({
      ...initialState,
      dimensions: generateDimensionsFromTemplate('full'),
      global: createDefaultGlobal(),
      isDirty: false,
      isSaving: false,
      isCollecting: false,
      collectProgress: 0,
      error: null,
    })
    withBroadcast(EVENT_NAMES.DATA_TEST_CHANGED, { action: 'reset' })
  },

  saveConfig: async () => {
    const state = get()
    if (state.isSaving) return

    set({ isSaving: true, error: null })

    try {
      const config = buildCollectionConfig(state)
      logger.info('[SevenDimConfigStore] 保存采集配置', {
        template: config.activeTemplate,
        enabledCount: state.enabledCount(),
        symbolCount: config.symbolCount,
      })

      await dataBridge.forward({
        meta: {
          source: MODULE_ID.fetcher,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.saveCollectConfig,
          traceId: `save-collect-config-${Date.now()}`,
          timestamp: Date.now(),
        },
        payload: {
          store: STORE_NAME.collectConfig,
          data: { id: COLLECT_CONFIG_ID, ...config },
        },
      })

      set({ isSaving: false, isDirty: false })
      logger.info('[SevenDimConfigStore] 配置保存成功')
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[SevenDimConfigStore] 配置保存失败', { error: message })
      set({ isSaving: false, error: message })
    }
  },

  loadConfig: async () => {
    try {
      logger.info('[SevenDimConfigStore] 从 IndexedDB 加载采集配置')
      const result = await dataBridge.query<Record<string, unknown>>({
        action: 'QUERY_GET',
        store: STORE_NAME.collectConfig,
        key: COLLECT_CONFIG_ID,
        source: MODULE_ID.fetcher,
      })

      if (!result.success || !result.data) {
        logger.info('[SevenDimConfigStore] 未找到已保存配置，使用默认配置')
        return
      }

      const raw = result.data
      const loadedConfig: CollectionConfig = {
        version: typeof raw.version === 'string' ? raw.version : '1.0.0',
        activeTemplate: (raw.activeTemplate as StrategyTemplateId) ?? 'value',
        dimensions: Array.isArray(raw.dimensions)
          ? upgradeDimensionsToPipeline(raw.dimensions as DimensionPipelineConfig[])
          : createPipelineDimensions(),
        global: raw.global ? (raw.global as GlobalCollectPolicy) : createDefaultGlobal(),
        symbolCount: typeof raw.symbolCount === 'number' ? raw.symbolCount : 40,
        historyDays: typeof raw.historyDays === 'number' ? raw.historyDays : 252,
        updatedAt: typeof raw.updatedAt === 'number' ? raw.updatedAt : Date.now(),
      }

      set({
        activeTemplate: loadedConfig.activeTemplate,
        dimensions: loadedConfig.dimensions,
        global: loadedConfig.global,
        symbolCount: loadedConfig.symbolCount,
        historyDays: loadedConfig.historyDays,
        isDirty: false,
        error: null,
      })

      logger.info('[SevenDimConfigStore] 配置加载成功', {
        activeTemplate: loadedConfig.activeTemplate,
        enabledCount: loadedConfig.dimensions.filter((d) => d.enabled).length,
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[SevenDimConfigStore] 配置加载失败', { error: message })
      set({ error: message })
    }
  },

  runCollection: async () => {
    const state = get()
    if (state.collectingDimensions.length > 0) return

    const enabledDims = state.dimensions.filter((d) => d.enabled)
    const symbols = resolveDefaultSymbols(state.symbolCount)
    if (enabledDims.length === 0 || symbols.length === 0) {
      logger.warn('[SevenDimConfigStore] 无可用维度或标的，跳过采集')
      return
    }

    // Palantir Foundry 对标：维度就绪度检查（采集前验证配置完整性）
    const unreadyDims = enabledDims.filter((d) => !d.code || d.sources.length === 0)
    if (unreadyDims.length > 0) {
      const unreadyCodes = unreadyDims.map((d) => d.code).join(', ')
      logger.warn('[SevenDimConfigStore] 维度就绪度检查未通过', {
        unreadyDimensions: unreadyCodes,
        reason: '缺少 code 或 sources 为空',
      })
      set({ error: `维度配置不完整: ${unreadyCodes}（缺少 code 或数据源）` })
      return
    }

    const dimCodes = enabledDims.map((d) => d.code)
    set({
      isCollecting: true,
      collectingDimensions: [...dimCodes],
      collectProgress: 0,
      error: null,
    })
    const runtime = useCollectionRuntimeStore.getState()
    runtime.setRunning(true)

    const config = buildCollectionConfig(state)
    const parentTaskId = `collect-${Date.now()}`

    logger.info('[SevenDimConfigStore] 开始并发采集', {
      dimensions: dimCodes.join(', '),
      symbolCount: symbols.length,
      parentTaskId,
    })

    try {
      const results = await Promise.allSettled(
        dimCodes.map((dimCode) =>
          runBatchTrace({ symbols, dimensionCode: dimCode, config, parentTaskId }),
        ),
      )

      const failures = results.filter((r) => r.status === 'rejected')
      set({
        isCollecting: false,
        collectingDimensions: [],
        collectProgress: 100,
        error: failures.length > 0
          ? `${failures.length} 个维度采集失败`
          : null,
      })
      runtime.setRunning(false)
      runtime.refreshStats()

      if (failures.length > 0) {
        const errMsg = failures
          .map((f) => (f as PromiseRejectedResult).reason)
          .join('; ')
        logger.error('[SevenDimConfigStore] 并发采集部分失败', { failures: failures.length, errors: errMsg })
      } else {
        logger.info('[SevenDimConfigStore] 并发采集完成')
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[SevenDimConfigStore] 采集失败', { error: message })
      runtime.setRunning(false)
      set({ isCollecting: false, collectingDimensions: [], error: message })
    }
  },

  clearError: () => set({ error: null }),
}))

/**
 * @module signalQualityStore
 * @lifecycle @Global
 * @description 信号质量复盘状态管理。管理信号准确率、择时得分、最大回撤、Sharpe 等
 * 绩效指标，提供复盘数据加载和 DataBridge 订阅。
 *
 * @status 当前无 UI 消费方。经补充验证（2026-07-06）确认：
 * 1. 与 outputStore 零数据交互，outputStore 是纯导出工具 Store
 * 2. OutputApp 子页面（TradeReviewPage/ResearchReportPage/OutputHubPage）均不引用此 Store
 * 3. TradeReviewPage 使用 disciplineStore + tradeReviewAI（基于订单的纪律复盘），
 *    与本 Store（基于信号的准确率复盘）是不同维度的复盘体系，数据模型不兼容
 * 4. SIGNAL_QUALITY_CHANGED 事件零订阅者
 * 5. initSignalQualityStoreSubscriptions() 从未被调用，无自动更新机制
 *
 * 保留以备未来**信号质量复盘面板**（如 SignalQualityDashboard）使用。
 * 注意：与现有 TradeReviewPage（基于 disciplineStore 的订单复盘）是不同维度的复盘体系，不可混淆。
 * 删除前需确认未来无信号准确率复盘可视化需求。
 *
 * @see 补充验证报告（2026-07-06）：见上方 JSDoc 注释 1-5 条
  * @doc [V9-DOC-ARCH-007, V9-DOC-DATA-031, V9-DOC-DATA-032, V9-DOC-BACK-015, V9-DOC-DATA-076]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { ENVELOPE_ACTION, MODULE_ID, STORE_NAME, type EnvelopeAction } from '@/config/dbConfig'
import type { Signal } from '@/data/types'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/store/helpers/withBroadcast'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

/** 信号质量指标 */
export interface SignalQualityMetrics {
  /** 信号总数 */
  totalSignals: number
  /** 已实现信号数（有后续价格数据） */
  realizedSignals: number
  /** 准确率（0-1）：信号方向与实际走势一致的比例 */
  accuracy: number
  /** 择时得分（0-100）：基于信号发出时机与实际拐点的时间差 */
  timingScore: number
  /** 最大回撤（0-1，负值表示亏损） */
  maxDrawdown: number
  /** Sharpe 比率 */
  sharpeRatio: number
  /** 平均持仓天数 */
  avgHoldingDays: number
  /** 胜率（0-1） */
  winRate: number
  /** 盈亏比 */
  profitLossRatio: number
}

/** 单个信号的复盘记录 */
export interface SignalReviewRecord {
  signalId: string
  symbol: string
  direction: 'buy' | 'sell' | 'hold' | 'watch'
  type: string
  confidence: number
  issuedAt: number
  /** 信号发出后 N 日的实际走势 */
  actualReturn?: number
  /** 信号是否正确 */
  correct?: boolean
  /** 持仓天数 */
  holdingDays?: number
  /** 盈亏百分比 */
  pnlPercent?: number
}

// ============================================================
// Store 接口
// ============================================================

interface SignalQualityState {
  /** 质量指标 */
  metrics: SignalQualityMetrics | null
  /** 复盘记录列表 */
  reviews: SignalReviewRecord[]
  /** 加载状态 */
  loading: boolean
  /** 错误信息 */
  error: string | null
  /** 最后更新时间戳 */
  lastUpdated: number

  // Actions
  /** 加载复盘数据 */
  loadReviews: () => Promise<void>
  /** 重新计算质量指标 */
  recalculateMetrics: () => void
}

// ============================================================
// 辅助函数
// ============================================================

function calculateMetrics(reviews: SignalReviewRecord[]): SignalQualityMetrics {
  const totalSignals = reviews.length
  const realizedReviews = reviews.filter((r) => r.actualReturn !== undefined)
  const realizedSignals = realizedReviews.length

  if (realizedSignals === 0) {
    return {
      totalSignals,
      realizedSignals: 0,
      accuracy: 0,
      timingScore: 0,
      maxDrawdown: 0,
      sharpeRatio: 0,
      avgHoldingDays: 0,
      winRate: 0,
      profitLossRatio: 0,
    }
  }

  // 准确率
  const correctCount = realizedReviews.filter((r) => r.correct).length
  const accuracy = correctCount / realizedSignals

  // 过滤 pnlPercent 非空的记录，用于胜率/盈亏比/回撤/Sharpe 计算
  const pnlReviews = realizedReviews.filter((r) => r.pnlPercent != null)
  const pnlMissingCount = realizedSignals - pnlReviews.length
  if (pnlMissingCount > 0) {
    logger.warn('[SignalQuality] pnlPercent 缺失', { missingCount: pnlMissingCount, totalCount: realizedSignals })
  }

  // 胜率（基于有 pnlPercent 的记录）
  const pnlBase = pnlReviews.length > 0 ? pnlReviews : realizedReviews
  const winningTrades = pnlBase.filter((r) => (r.pnlPercent as number) > 0).length
  const winRate = winningTrades / pnlBase.length

  // 盈亏比
  const avgWin =
    pnlBase.filter((r) => (r.pnlPercent as number) > 0).reduce((sum, r) => sum + (r.pnlPercent as number), 0) /
    Math.max(winningTrades, 1)
  const losingTrades = pnlBase.filter((r) => (r.pnlPercent as number) < 0)
  const avgLoss =
    Math.abs(
      losingTrades.reduce((sum, r) => sum + (r.pnlPercent as number), 0) /
        Math.max(pnlBase.length - winningTrades, 1),
    )
  const profitLossRatio = avgLoss > 0 ? avgWin / avgLoss : 0

  // 平均持仓天数（过滤 null 值）
  const holdingDaysReviews = realizedReviews.filter((r) => r.holdingDays != null)
  const holdingDaysMissing = realizedSignals - holdingDaysReviews.length
  if (holdingDaysMissing > 0) {
    logger.warn('[SignalQuality] holdingDays 缺失', { missingCount: holdingDaysMissing, totalCount: realizedSignals })
  }
  const holdingDaysList = holdingDaysReviews.map((r) => r.holdingDays as number)
  const avgHoldingDays = holdingDaysList.length > 0
    ? holdingDaysList.reduce((sum, d) => sum + d, 0) / holdingDaysList.length
    : 0

  // 最大回撤（简化计算：取最小 pnlPercent）
  const pnlValues = pnlBase.map((r) => r.pnlPercent as number)
  const maxDrawdown = pnlValues.length > 0 ? Math.min(0, ...pnlValues) / 100 : 0

  // Sharpe 比率（简化：假设无风险利率为 0）
  const returns = pnlValues.map((p) => p / 100)
  const avgReturn = returns.length > 0 ? returns.reduce((sum, r) => sum + r, 0) / returns.length : 0
  const stdDev = returns.length > 0
    ? Math.sqrt(returns.reduce((sum, r) => sum + (r - avgReturn) ** 2, 0) / returns.length)
    : 0
  const sharpeRatio = stdDev > 0 ? avgReturn / stdDev : 0

  // 择时得分（简化：基于信号置信度与实际收益的相关性）
  const timingScore = Math.min(100, accuracy * 100 * 0.7 + winRate * 100 * 0.3)

  return {
    totalSignals,
    realizedSignals,
    accuracy,
    timingScore,
    maxDrawdown,
    sharpeRatio,
    avgHoldingDays,
    winRate,
    profitLossRatio,
  }
}

