// 派生查询（从 .derived.ts 统一导出，含 memoizeByRef 缓存优化）
// 设计原则：派生查询独立函数模式，通过 getState() 访问状态，不存入 State
// 原 Store 中的 reviewsBySymbol/topSignalTypes 已由 .derived.ts 的缓存版本替代
// ============================================================
export * from './signalQualityStore.derived'

// ============================================================
// DataBridge 订阅
