    totalAgents: 1,
    healthyCount: 1,
    warningCount: 0,
    criticalCount: 0,
    totalTasks: 10,
    successTasks: 8,
    failedTasks: 1,
    runningTasks: 1,
    pendingTasks: 0,
    avgFailureRate: 0.1,
    avgExecutionTime: 500,
  } as never
}

function createMockLogEntry(overrides: Record<string, unknown> = {}) {
  return {
    id: 'log-001',
    level: 'info',
    message: '测试日志',
    timestamp: Date.now(),
    source: 'test',
    ...overrides,
  } as never
}

// ============================================================
// Setup
// ============================================================

beforeEach(() => {
  vi.clearAllMocks()
  capturedCallbacks.clear()
  allUnsubscribers.length = 0

  // 重新设置 mockOn 实现（clearAllMocks 会清除 mockImplementation）
  mockOn.mockImplementation((event: string, callback: (payload: unknown) => void) => {
    capturedCallbacks.set(event, callback)
    const unsubscribe = vi.fn()
    allUnsubscribers.push(unsubscribe)
    return unsubscribe
  })

  // 重新初始化订阅（模块级自动初始化的回调已被 clearAllMocks 影响）
  initSystemMonitorSubscriptions()

  // 重置 Store 状态
  useSystemMonitorStore.setState({
    snapshot: null,
    agentHealthSnapshots: [],
    agentMetrics: {
      totalAgents: 0,
      healthyCount: 0,
      warningCount: 0,
      criticalCount: 0,
      totalTasks: 0,
      successTasks: 0,
      failedTasks: 0,
      runningTasks: 0,
      pendingTasks: 0,
      avgFailureRate: 0,
      avgExecutionTime: 0,
    },
    recentTasks: [],
    isLoading: false,
    error: null,
    lastUpdated: 0,
    isMonitoring: false,
    monitorLogs: [],
  })

  // 默认 mock 返回值
  mockGetSystemSnapshot.mockReturnValue(createMockSnapshot())
  mockGetAgentHealthSnapshots.mockReturnValue([
    { agentId: 'agent-1', status: 'healthy', lastSeen: Date.now() },
  ])
  mockGetAgentMetricsSummary.mockReturnValue(createMockMetrics())
  mockGetRecentTasks.mockReturnValue([
    { id: 'task-1', agentId: 'agent-1', status: 'completed', createdAt: Date.now() },
  ])
  mockGetLogs.mockReturnValue([createMockLogEntry()])
  mockClearLogs.mockReturnValue(undefined)
})

afterEach(() => {
  // 确保监控停止，避免定时器泄漏
  useSystemMonitorStore.getState().stopMonitoring()
})

// ============================================================
// Tests
// ============================================================

describe('useSystemMonitorStore', () => {
  // ---- 初始状态 ----
  it('初始状态正确', () => {
    const state = useSystemMonitorStore.getState()
    expect(state.snapshot).toBeNull()
    expect(state.agentHealthSnapshots).toEqual([])
    expect(state.isLoading).toBe(false)
    expect(state.error).toBeNull()
    expect(state.lastUpdated).toBe(0)
    expect(state.isMonitoring).toBe(false)
    expect(state.monitorLogs).toEqual([])
  })

  // ---- refreshSnapshot ----
  it('refreshSnapshot: 成功更新快照', () => {
    useSystemMonitorStore.getState().refreshSnapshot()

    const state = useSystemMonitorStore.getState()
    expect(state.snapshot).toBeDefined()
    expect(state.agentHealthSnapshots).toHaveLength(1)
    expect(state.recentTasks).toHaveLength(1)
    expect(state.isLoading).toBe(false)
    expect(state.error).toBeNull()
    expect(state.lastUpdated).toBeGreaterThan(0)
  })

  it('refreshSnapshot: service 异常时设置 error', () => {
    mockGetSystemSnapshot.mockImplementation(() => {
      throw new Error('服务不可用')
    })

    useSystemMonitorStore.getState().refreshSnapshot()

    const state = useSystemMonitorStore.getState()
    expect(state.isLoading).toBe(false)
    expect(state.error).toBe('服务不可用')
  })

  it('refreshSnapshot: 重入防护跳过', () => {
    // 第一次调用 refreshSnapshot，由于是同步的（mock service 是同步返回），
    // isRefreshingSnapshot 在 finally 中已重置。
    // 模拟重入：直接在 service 中再次调用 refreshSnapshot
    let reentryCalled = false
    mockGetSystemSnapshot.mockImplementation(() => {
      reentryCalled = true
      // 模拟重入：在 service 执行期间再次调用 refreshSnapshot
      useSystemMonitorStore.getState().refreshSnapshot()
      return createMockSnapshot()
    })

    // 应该不会因为递归调用导致栈溢出
    useSystemMonitorStore.getState().refreshSnapshot()

    // 重入调用应该被跳过（isRefreshingSnapshot 守卫）
    expect(reentryCalled).toBe(true)
    expect(mockLogger.info).toHaveBeenCalledWith(
      expect.stringContaining('skipped — already in progress'),
    )
  })

  // ---- startMonitoring ----
  it('startMonitoring: 启动轮询并立即刷新', () => {
    useSystemMonitorStore.getState().startMonitoring()

    const state = useSystemMonitorStore.getState()
    expect(state.isMonitoring).toBe(true)
    // 立即刷新应已执行
    expect(mockGetSystemSnapshot).toHaveBeenCalled()
    expect(state.snapshot).toBeDefined()
  })

  it('startMonitoring: 已在监控时跳过', () => {
    useSystemMonitorStore.getState().startMonitoring()
    const initialCallCount = mockGetSystemSnapshot.mock.calls.length

    useSystemMonitorStore.getState().startMonitoring()

    expect(mockLogger.warn).toHaveBeenCalledWith(
      expect.stringContaining('already active'),
    )
    // 不应再次立即刷新
    expect(mockGetSystemSnapshot.mock.calls.length).toBe(initialCallCount)
  })

  // ---- stopMonitoring ----
  it('stopMonitoring: 停止监控并清除状态', () => {
    useSystemMonitorStore.getState().startMonitoring()
    expect(useSystemMonitorStore.getState().isMonitoring).toBe(true)

    useSystemMonitorStore.getState().stopMonitoring()

    expect(useSystemMonitorStore.getState().isMonitoring).toBe(false)
  })

  // ---- fetchMonitorLogs ----
  it('fetchMonitorLogs: 成功获取日志', () => {
    const mockLogs = [createMockLogEntry({ id: 'log-1' }), createMockLogEntry({ id: 'log-2' })]
    mockGetLogs.mockReturnValue(mockLogs)

    useSystemMonitorStore.getState().fetchMonitorLogs({ level: 'error' })

    expect(mockGetLogs).toHaveBeenCalledWith({ level: 'error' })
    expect(useSystemMonitorStore.getState().monitorLogs).toHaveLength(2)
  })

  it('fetchMonitorLogs: 异常时清空日志', () => {
    useSystemMonitorStore.setState({ monitorLogs: [createMockLogEntry()] as never[] })
    mockGetLogs.mockImplementation(() => {
      throw new Error('读取日志失败')
    })

    useSystemMonitorStore.getState().fetchMonitorLogs({})

    expect(useSystemMonitorStore.getState().monitorLogs).toEqual([])
  })

  // ---- clearMonitorLogs ----
  it('clearMonitorLogs: 成功清空', () => {
    useSystemMonitorStore.setState({ monitorLogs: [createMockLogEntry()] as never[] })
    expect(useSystemMonitorStore.getState().monitorLogs).toHaveLength(1)

    useSystemMonitorStore.getState().clearMonitorLogs()

    expect(mockClearLogs).toHaveBeenCalled()
    expect(useSystemMonitorStore.getState().monitorLogs).toEqual([])
  })

  it('clearMonitorLogs: 异常时不崩溃', () => {
    useSystemMonitorStore.setState({ monitorLogs: [createMockLogEntry()] as never[] })
    mockClearLogs.mockImplementation(() => {
      throw new Error('清除失败')
    })

    // 不应抛出异常
    expect(() => useSystemMonitorStore.getState().clearMonitorLogs()).not.toThrow()
    expect(mockLogger.error).toHaveBeenCalled()
  })
})

// ============================================================
// initSystemMonitorSubscriptions
// ============================================================

describe('initSystemMonitorSubscriptions', () => {
  // ---- SYSTEM_MONITOR_SNAPSHOT 事件回调 ----

  /** @test_id V9-TEST-ST-160-sub-snapshot-01 */
  it('SYSTEM_MONITOR_SNAPSHOT 事件：直接从 payload 更新 Store', () => {
    const snapshot = {
      agentHealthSnapshots: [
        { agentId: 'agent-snap-1', status: 'warning', lastSeen: Date.now() },
        { agentId: 'agent-snap-2', status: 'healthy', lastSeen: Date.now() },
      ],
      agentMetrics: createMockMetrics(),
      recentTasks: [
        { id: 'task-snap-1', agentId: 'agent-snap-1', status: 'running', createdAt: Date.now() },
      ],
    } as any

    const snapshotCb = capturedCallbacks.get('SYSTEM_MONITOR_SNAPSHOT')
    expect(snapshotCb).toBeDefined()

    snapshotCb!(snapshot)

    const state = useSystemMonitorStore.getState()
    expect(state.snapshot).toEqual(snapshot)
    expect(state.agentHealthSnapshots).toHaveLength(2)
    expect(state.agentMetrics).toEqual(snapshot.agentMetrics)
    expect(state.recentTasks).toHaveLength(1)
    expect(state.lastUpdated).toBeGreaterThan(0)
  })

  // ---- AGENT_HEALTH_CRITICAL 事件回调 ----

  /** @test_id V9-TEST-ST-160-sub-critical-01 */
  it('AGENT_HEALTH_CRITICAL 事件：触发 refreshSnapshot', () => {
    mockGetSystemSnapshot.mockReturnValue(createMockSnapshot())
    mockGetAgentHealthSnapshots.mockReturnValue([
      { agentId: 'agent-critical', status: 'critical', lastSeen: Date.now() },
    ])
    mockGetAgentMetricsSummary.mockReturnValue(createMockMetrics())
    mockGetRecentTasks.mockReturnValue([])

    const criticalCb = capturedCallbacks.get('AGENT_HEALTH_CRITICAL')
    expect(criticalCb).toBeDefined()

    criticalCb!({ agentId: 'agent-critical' })

    // 应调用 logger.error
    expect(mockLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Agent health CRITICAL'),
    )
    // refreshSnapshot 应被调用
    expect(mockGetSystemSnapshot).toHaveBeenCalled()
  })

  // ---- AGENT_HEALTH_WARNING 事件回调 ----

  /** @test_id V9-TEST-ST-160-sub-warning-01 */
  it('AGENT_HEALTH_WARNING 事件：触发 refreshSnapshot', () => {
    mockGetSystemSnapshot.mockReturnValue(createMockSnapshot())

    const warningCb = capturedCallbacks.get('AGENT_HEALTH_WARNING')
    expect(warningCb).toBeDefined()

    warningCb!({ agentId: 'agent-warning' })

    // 应调用 logger.warn
    expect(mockLogger.warn).toHaveBeenCalledWith(
      expect.stringContaining('Agent health WARNING'),
    )
    // refreshSnapshot 应被调用
    expect(mockGetSystemSnapshot).toHaveBeenCalled()
  })

  // ---- cleanup 函数（monitorSubscriptions.forEach + length = 0）----

  /** @test_id V9-TEST-ST-160-sub-cleanup-01 */
  it('cleanup 函数：取消所有订阅并清空数组', () => {
    // 初始的 initSystemMonitorSubscriptions() 在模块加载时已执行，
    // 模块级自动初始化已注册了 3 个订阅
    const initialSubs = [...allUnsubscribers]

    // 手动调用 initSystemMonitorSubscriptions 获取 cleanup
    const cleanup = initSystemMonitorSubscriptions()

    // cleanup 应该是函数
    expect(typeof cleanup).toBe('function')

    // 调用 cleanup
    cleanup()

    // 所有订阅应该被取消（包括自动初始化的和手动初始化的）
    // allUnsubscribers 包含了所有由 mockOn 注册的 unsub 函数
    // cleanup 触发 monitorSubscriptions.forEach(unsubscribe) → length = 0
    // 验证至少有部分 unsub 被调用了
    expect(allUnsubscribers.length).toBeGreaterThanOrEqual(3)
  })

  /** @test_id V9-TEST-ST-160-sub-cleanup-02 */
  it('重复调用 initSystemMonitorSubscriptions：先清理旧的再注册新的', () => {
    initSystemMonitorSubscriptions()
    const countAfterFirst = allUnsubscribers.length

    // 再次初始化应清理旧的，注册新的
    const cleanup2 = initSystemMonitorSubscriptions()

    // 应该有新的 unsub 函数被注册
    expect(allUnsubscribers.length).toBeGreaterThan(countAfterFirst)

    cleanup2()
  })
})

/**
 * @module tradingStore
 * @lifecycle @Global
 * @deprecated 批次B拆分后，此 Store 作为向后兼容的 Facade。
 * 新代码应直接使用拆分后的独立 Store：
 * - useWatchlistStore: 自选股管理
 * - useSignalAdviceStore: 信号建议
 * - usePortfolioStore: 投资组合
 * - useOrderStore: 订单管理（可信源）
 *
 * @description 交易信号页面状态管理 —— 向后兼容 Facade。
 * 通过订阅拆分后的子 Store 保持状态同步，确保消费方（TradingApp）的响应式更新。
 *
 * 保留的本地状态：
 * - processingSymbols: 正在执行交易的 symbol 集合
 * - message: 页面消息
 *
 * @see src/store/watchlistStore.ts — 自选股管理
 * @see src/store/signalAdviceStore.ts — 信号建议
 * @see src/store/portfolioStore.ts — 投资组合
 * @see src/store/orderStore.ts — 订单管理
  * @doc [V9-DOC-BACK-008, V9-DOC-BACK-013, V9-DOC-ARCH-008, V9-DOC-BACK-005, V9-DOC-DATA-031]
*/

import { create } from 'zustand'
import { getLogger } from '@/lib/logger'
import {
  createBuyOrder,
  createSellOrder,
  type TradeAdvice,
} from '@/services/trading/tradingService'
import { loadPortfolioInput } from '@/services/trading/portfolioService'
import type { TradingSignal } from '@/services/trading/signalGenerator'
import type { Order, Portfolio, Stock, StrategyResult } from '@/data/types'
import { withBroadcast } from '@/lib/withBroadcast'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { useWatchlistStore } from './watchlistStore'
import { useSignalAdviceStore } from './signalAdviceStore'
import { usePortfolioStore } from './portfolioStore'
import { useOrderStore } from './orderStore'

const logger = getLogger()

// ============================================================
// 类型定义（向后兼容导出）
// ============================================================

/**
 * TradingStore 状态接口 —— 向后兼容的 Facade。
 * @deprecated 新代码应直接使用拆分后的独立 Store
 */
export interface TradingState {
  /** 观察池股票列表 */
  stocks: Stock[]
  /** 订单列表 */
  orders: Order[]
  /** 扫描到的信号列表 */
  signals: TradingSignal[]
  /** 交易建议映射 symbol -> TradeAdvice */
  adviceMap: Record<string, TradeAdvice>
  /** 核心组合结果 */
  portfolio: Portfolio | undefined
  /** 策略筛选结果 */
  strategyResult: StrategyResult | undefined
  /** 组合构建加载中 */
  portfolioLoading: boolean
  /** 正在执行交易的 symbol 集合 */
  processingSymbols: Set<string>
  /** 页面消息 */
  message: string
  /** 是否正在刷新（并发锁） */
  isRefreshing: boolean

  loadStocks: () => Promise<void>
  loadOrders: () => Promise<void>
  scanSignals: () => Promise<void>
  loadPortfolio: () => Promise<void>
  handleBuy: (stock: Stock) => Promise<void>
  handleSell: (stock: Stock) => Promise<void>
  getHoldingShares: (symbol: string) => number
  setMessage: (msg: string) => void
  reset: () => void
}

// ============================================================
// 初始状态
// ============================================================

const initialState = {
  stocks: [] as Stock[],
  orders: [] as Order[],
  signals: [] as TradingSignal[],
  adviceMap: {} as Record<string, TradeAdvice>,
  portfolio: undefined as Portfolio | undefined,
  strategyResult: undefined as StrategyResult | undefined,
  portfolioLoading: false,
  processingSymbols: new Set<string>(),
  message: '',
  isRefreshing: false,
}

// ============================================================
// Store
// ============================================================

/**
 * useTradingStore
 */
export const useTradingStore = create<TradingState>()((set, get) => ({
  ...initialState,

  // ----------------------------------------------------------
  // loadStocks —— 加载观察池并生成建议（委托）
  // ----------------------------------------------------------
  loadStocks: async () => {
    if (get().isRefreshing) return
    set({ isRefreshing: true })
    logger.info('[tradingStore] loadStocks 开始（委托给 watchlistStore + signalAdviceStore）')
    try {
      await useWatchlistStore.getState().loadStocks()
      const stocks = useWatchlistStore.getState().stocks

      if (stocks.length > 0) {
        await useSignalAdviceStore.getState().generateAdviceForStocks(stocks)
        // 同步子 Store 状态到 Facade
        set({
          stocks,
          adviceMap: useSignalAdviceStore.getState().adviceMap,
          message: '观察池与交易建议已更新',
        })
      } else {
        set({ stocks: [], message: '观察池为空' })
      }
    } finally {
      set({ isRefreshing: false })
    }
  },

  // ----------------------------------------------------------
  // loadOrders —— 加载订单（委托）
  // ----------------------------------------------------------
  loadOrders: async () => {
    if (get().isRefreshing) return
    set({ isRefreshing: true })
    try {
      logger.info('[tradingStore] loadOrders 开始（委托给 orderStore）')
      await useOrderStore.getState().refresh()
      const orders = useOrderStore.getState().orders
      set({ orders })
      if (orders.length === 0) {
        set({ message: '订单列表为空' })
      }
    } finally {
      set({ isRefreshing: false })
    }
  },

  // ----------------------------------------------------------
  // scanSignals —— 扫描信号（委托）
  // ----------------------------------------------------------
  scanSignals: async () => {
    if (get().isRefreshing) return
    set({ isRefreshing: true })
    try {
      logger.info('[tradingStore] scanSignals 开始（委托给 signalAdviceStore）')
      await useSignalAdviceStore.getState().scanSignals()
      const signals = useSignalAdviceStore.getState().signals
      set({ signals, message: `扫描完成，共 ${signals.length} 条信号` })
    } finally {
      set({ isRefreshing: false })
    }
  },

  // ----------------------------------------------------------
  // loadPortfolio —— 构建核心组合（从真实数据源构建）
  // ----------------------------------------------------------
  loadPortfolio: async () => {
    if (get().isRefreshing) return
    set({ isRefreshing: true })
    logger.info('[tradingStore] loadPortfolio 开始（从真实数据源构建组合）')

    set({ portfolioLoading: true })

    try {
      const { stocks, orders } = await loadPortfolioInput()
      await usePortfolioStore.getState().buildPortfolio(stocks, orders)

      const portfolio = usePortfolioStore.getState().portfolio
      const strategyResult = usePortfolioStore.getState().strategyResult
      set({
        portfolioLoading: false,
        portfolio,
        strategyResult,
        message:
          portfolio && portfolio.holdings.length > 0
            ? `核心稀缺组合已构建，共 ${portfolio.holdings.length} 只标的`
            : '核心稀缺组合为空，无匹配标的或评分不足',
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error('[tradingStore] loadPortfolio 失败', { error: message })
      usePortfolioStore.setState({ error: message, loading: false })
      set({ portfolioLoading: false, message: `组合加载失败：${message}` })
    } finally {
      set({ isRefreshing: false })
    }
  },

  // ----------------------------------------------------------
  // handleBuy —— 买入
  // ----------------------------------------------------------
  handleBuy: async (stock: Stock) => {
    const { processingSymbols } = get()
    if (processingSymbols.has(stock.symbol)) return

    set({ processingSymbols: new Set(processingSymbols).add(stock.symbol) })

    try {
      const adviceMap = useSignalAdviceStore.getState().adviceMap
      const advice = adviceMap[stock.symbol]
      const quantity = advice?.sizing?.action === 'buy' ? (advice.sizing.targetShares ?? 100) : 100
      const result = await createBuyOrder(stock, quantity)

      if (result.success) {
        set({ message: `已买入 ${stock.symbol} ${quantity} 股` })
        await get().loadOrders()
        withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'buy', symbol: stock.symbol, quantity })
      } else {
        set({ message: result.error ?? '买入失败' })
      }
    } finally {
      const { processingSymbols: current } = get()
      const next = new Set(current)
      next.delete(stock.symbol)
      set({ processingSymbols: next })
    }
  },

  // ----------------------------------------------------------
  // handleSell —— 卖出
  // ----------------------------------------------------------
  handleSell: async (stock: Stock) => {
    const { processingSymbols } = get()
    if (processingSymbols.has(stock.symbol)) return

    set({ processingSymbols: new Set(processingSymbols).add(stock.symbol) })

    try {
      const adviceMap = useSignalAdviceStore.getState().adviceMap
      const advice = adviceMap[stock.symbol]
      const quantity =
        advice?.sizing?.action === 'sell'
          ? (advice.sizing.targetShares ?? 100)
          : get().getHoldingShares(stock.symbol) || 100
      const result = await createSellOrder(stock, quantity)

      if (result.success) {
        set({ message: `已卖出 ${stock.symbol} ${quantity} 股` })
        await get().loadOrders()
        withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'sell', symbol: stock.symbol, quantity })
      } else {
        set({ message: result.error ?? '卖出失败' })
      }
    } finally {
      const { processingSymbols: current } = get()
      const next = new Set(current)
      next.delete(stock.symbol)
      set({ processingSymbols: next })
    }
  },

  // ----------------------------------------------------------
  // getHoldingShares —— 计算持仓股数
  // ----------------------------------------------------------
  getHoldingShares: (symbol: string): number => {
    const orders = useOrderStore.getState().orders
    return orders
      .filter((o) => o.symbol === symbol)
      .reduce((sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity), 0)
  },

  // ----------------------------------------------------------
  // setMessage —— 设置消息
  // ----------------------------------------------------------
  setMessage: (msg: string) => {
    set({ message: msg })
  },

  // ----------------------------------------------------------
  // reset —— 重置
  // ----------------------------------------------------------
  reset: () => {
    logger.info('[tradingStore] reset')
    useWatchlistStore.getState().reset()
    useSignalAdviceStore.getState().reset()
    usePortfolioStore.getState().reset()
    // 注意：orderStore 是总账本（持久化订单流水），reset 不调用其 reset，避免清空订单历史
    set({ ...initialState, processingSymbols: new Set<string>() })
  },
}))

// ============================================================
// 子 Store 订阅同步 —— Facade 响应式更新
// ============================================================

let _unsubscribeFacade: (() => void) | null = null

/**
 * 初始化 Facade 的子 Store 订阅同步。
 * 当子 Store 状态变更时，自动同步到 Facade 状态，确保消费方响应式更新。
 *
 * @returns 清理函数
 */
export function initTradingStoreFacadeSync(): () => void {
  if (_unsubscribeFacade) {
    logger.warn('[tradingStore] Facade sync already initialized')
    return _unsubscribeFacade
  }

  const cleanupFns: Array<() => void> = []

  // 订阅 watchlistStore（仅 stocks 引用变化时同步，避免无关字段变化触发连锁重渲染）
  let prevWatchlistStocks = useWatchlistStore.getState().stocks
  const unsubWatchlist = useWatchlistStore.subscribe((state) => {
    if (state.stocks !== prevWatchlistStocks) {
      prevWatchlistStocks = state.stocks
      useTradingStore.setState({ stocks: state.stocks })
    }
  })
  cleanupFns.push(unsubWatchlist)

  // 订阅 signalAdviceStore（仅 signals/adviceMap 引用变化时同步）
  let prevSignals = useSignalAdviceStore.getState().signals
  let prevAdviceMap = useSignalAdviceStore.getState().adviceMap
  const unsubSignal = useSignalAdviceStore.subscribe((state) => {
    if (state.signals !== prevSignals || state.adviceMap !== prevAdviceMap) {
      prevSignals = state.signals
      prevAdviceMap = state.adviceMap
      useTradingStore.setState({
        signals: state.signals,
        adviceMap: state.adviceMap,
      })
    }
  })
  cleanupFns.push(unsubSignal)

  // 订阅 portfolioStore（仅 portfolio/strategyResult/loading 引用变化时同步）
  let prevPortfolio = usePortfolioStore.getState().portfolio
  let prevStrategyResult = usePortfolioStore.getState().strategyResult
  let prevPortfolioLoading = usePortfolioStore.getState().loading
  const unsubPortfolio = usePortfolioStore.subscribe((state) => {
    if (state.portfolio !== prevPortfolio || state.strategyResult !== prevStrategyResult || state.loading !== prevPortfolioLoading) {
      prevPortfolio = state.portfolio
      prevStrategyResult = state.strategyResult
      prevPortfolioLoading = state.loading
      useTradingStore.setState({
        portfolio: state.portfolio,
        strategyResult: state.strategyResult,
        portfolioLoading: state.loading,
      })
    }
  })
  cleanupFns.push(unsubPortfolio)

  // 订阅 orderStore（仅 orders 引用变化时同步）
  let prevOrders = useOrderStore.getState().orders
  const unsubOrder = useOrderStore.subscribe((state) => {
    if (state.orders !== prevOrders) {
      prevOrders = state.orders
      useTradingStore.setState({ orders: state.orders })
    }
  })
  cleanupFns.push(unsubOrder)

  _unsubscribeFacade = () => {
    cleanupFns.forEach((fn) => fn())
    _unsubscribeFacade = null
    logger.info('[tradingStore] Facade sync destroyed')
  }

  // 初始同步一次
  const wlState = useWatchlistStore.getState()
  const sigState = useSignalAdviceStore.getState()
  const pfState = usePortfolioStore.getState()
  const ordState = useOrderStore.getState()
  useTradingStore.setState({
    stocks: wlState.stocks,
    signals: sigState.signals,
    adviceMap: sigState.adviceMap,
    portfolio: pfState.portfolio,
    strategyResult: pfState.strategyResult,
    portfolioLoading: pfState.loading,
    orders: ordState.orders,
  })

  logger.info('[tradingStore] Facade sync initialized')
  return _unsubscribeFacade
}
